local unsigned = {
[ "u32_add" ] = "+" ,
[ "u32_sub" ] = "-" ,
[ "u32_mul" ] = "*" ,
[ "u32_and" ] = "&" ,
[ "u32_or" ] = "|" ,
[ "u32_xor" ] = "^" ,
