elseif operation == "vsplat" then
return "ks_splat_" .. vector .. "(" .. emit . lane ( ( node ) . args [ 1 ] ) .. ")"
elseif operation == "vbool_splat" then

return "ks_bool_mask_" .. vector .. "(" .. emit . lane ( ( node ) . args [ 1 ] ) .. ")"
