name ,  cName =
kernel . symbol .. "_helper_" .. scalarIR . privateSymbol ( name ) : sub ( 4 ) ,  params =
params ,  values =
{ } ,  resultType =
resultTypes [ 1 ] ,  resultTypes =
resultTypes ,  source =
lower . site ( declaration ) }, scalarIR.Helper)

