)
scalarWalk ( event . capacity , values , scope )
elseif event . op == "lua_builder_key" or event . op == "lua_builder_string" then
holds (
event . sourceBytes ~= nil and (
event . sourceBytes
) . type == "lua_string" and event . start ~= nil and (
event . start
) . type == "u32" and event . length ~= nil and (
event . length
) . type == "u32" and event . escaped ~= nil and ( event . escaped ) . type == "bool" ,
"invalid value stream string event"
)
