end
local source = fs . join ( directory , record . artifact )
local text , readErr = fs . readFile ( source )
if not text then
return nil , "cannot read required stub " .. source .. ": " .. tostring ( readErr )
end
local valid , validErr = validateBytes ( record , text , source )
if not valid then
return nil , validErr
end




