return nil , "cannot cache stub " .. cached .. ": " .. tostring ( writeErr )
end
os . remove ( cached )
local renamed , renameErr = os . rename ( temporary , cached )
if not renamed then
os . remove ( temporary )
return nil , "cannot install cached stub " .. cached .. ": " .. tostring ( renameErr )
end

return cached
end

