return true
end
end
for _ , result in ipairs ( t . rets ) do
if compilerOnlyValue ( result ) then
return true
end
end
elseif t . tag == "intersection" or t . tag == "union" then
for _ , member in ipairs ( t . members ) do
if compilerOnlyValue ( member ) then
return true
end
end
end

return false
end





