local function operationSpec ( name , summary , usage , extra , schema )
local declared = { { name = "--root" , value = "DIR" , help = "Project root (default: current directory)" } , }
for _ , option in ipairs ( extra ) do
declared [ # declared + 1 ] = option
end
for _ , option in ipairs ( optionsMod . format ( ) ) do
declared [ # declared + 1 ] = option
end

return spec . command {
name = "lsp " .. name ,


helpName = "lsp" ,
summary = summary ,
usage = { usage } ,
options = declared ,
schema = schema ,
}
end


