name = name ,
kind = kind ,
signature = signature ,
doc = info ,
path = itemPath ,
module = itemModule ,
line = firstToken ( stat ) and firstToken ( stat ) . line or 1 ,
members = { } ,
params = { } ,
returns = { } ,
