related = { "NUPP2118" , "NUPP2006" } ,
docs = "docs/concepts/metamethods.md" ,
} ,
{
code = "NUPP2124" ,
summary = "An intersection is provably uninhabited" ,
rule = "A value of `A & B` must satisfy both contracts. Nupp reports only "
