writeValue and keyOf ( state , writeValue ) or "-" ,
}
made = make (
state ,
opaque ,
"Type" ,
{
kind = "indexer" ,
readKey = readKey ,
readValue = readValue ,
writeKey = writeKey ,
writeValue = writeValue ,
