local n = setmetatable({ kind =  "binop" }, cst.Binop)
n . lhs = add ( n , left )
n . op = add ( n , advance ( ) )
n . rhs = add ( n , parseBinexp ( pri [ 2 ] ) )
left = n
end
end

return left
end


