["/decls/prelude.d.nupp"] = [=[
--[[
# Nupp standard-library prelude

The `nupp` namespace itself: the intrinsics the compiler owns, and the ambient
library namespaces reached without a `require`. `nupp` loads this file into every
check environment with `declare_globals`, after `lua.d.nupp`, so the declarations
below may name Lua types such as `LuaFile`.

## Conventions

- Library tables are closed shapes, so a misspelled member is `NUPP2004`.
- What needs machinery that has not landed yet falls back to `any`.
- Every declaration carries a `---` docblock.

This file is parsed and checked by `nupp` itself, as is its Lua counterpart.
]]

--- Compiler-provided facilities. The namespace is always present; native members are
--- linked automatically when source reaches them.
---
--- @namespace nupp
local nupp: {

    --- Buffers, byte views, readers, writers, filesystem paths and URIs.
    io: nupp.io,

    --- Scalar helpers and two-dimensional vectors.
    math: nupp.MathLibrary,

    --- Cooperative development hot reload, installed by `nupp run --watch`.
    hotreload: nupp.HotReload,

    --- Compile and run byte-oriented parsing-expression grammars.
    --- @namespace
    peg: nupp.peg,

    --- Compiler-only type inspection and construction inside `comptime function`
    --- declarations. Every member is an ordinary checked compile-time value; none has
    --- a runtime representation.
    types: {
        readonly any: comptime type,
        readonly unknown: comptime type,
        readonly never: comptime type,
        readonly nil_: comptime type,
        readonly boolean: comptime type,
        readonly string: comptime type,
        readonly number: comptime type,
        readonly integer: comptime type,
        readonly table_: comptime type,
        readonly thread: comptime type,
        readonly userdata: comptime type,
        readonly float: comptime type,
        readonly cdata: comptime type,
        readonly cstring: comptime type,
        readonly voidptr: comptime type,
        readonly int8: comptime type,
        readonly int16: comptime type,
        readonly int32: comptime type,
        readonly int64: comptime type,
        readonly uint8: comptime type,
        readonly uint16: comptime type,
        readonly uint32: comptime type,
        readonly uint64: comptime type,

        readonly literal: comptime function(value: string | boolean | integer): type,
        readonly array: comptime function(element: type): type,
        readonly tuple: comptime function(elements: {type}): type,
        readonly union: comptime function(members: {type}): type,
        readonly intersection: comptime function(members: {type}): type,
        readonly optional: comptime function(inner: type): type,
        readonly pointer: comptime function(inner: type): type,
        readonly constof: comptime function(inner: type): type,
        readonly borrowed: comptime function(inner: type): type,
        readonly pinned: comptime function(inner: type): type,
        readonly affine: comptime function(representation: type): type
        & comptime function(representation: type, const terminal: function): type,
        readonly carray: comptime function(element: type, count: integer?): type,
        readonly indexer: comptime function(readKey: type?, readValue: type?, writeKey: type?, writeValue: type?): type,
        readonly map: comptime function(readKey: type, readValue: type, writeKey: type?, writeValue: type?): type,
        readonly shape: comptime function(fields: {{
            name: string,
            read: type?,
            write: type?
        }}, indexer: type?): type,
        readonly pack: comptime function(head: {type}, tail: type?, modes: {string}?): typepack,
        readonly function_: comptime function(parameters: typepack, results: typepack): type,
        readonly parameters: comptime function(callable: type): typepack,
        readonly results: comptime function(callable: type): typepack,
        readonly kind: comptime function(value: type | typepack): string,
        readonly describe: comptime function(value: type | typepack): {
            readonly kind: string,
            readonly sourceKind: string?,
            readonly name: string?,
            readonly value: (string | boolean | integer)?,
            readonly element: type?,
            readonly members: {type}?,
            readonly fields: {{
                name: string,
                read: type?,
                write: type?
            }}?,
            readonly indexer: type?,
            readonly readKey: type?,
            readonly readValue: type?,
            readonly writeKey: type?,
            readonly writeValue: type?,
            readonly nominal: boolean?,
            readonly head: {type}?,
            readonly tail: type?,
            readonly modes: {string}?,
            readonly count: integer?,
            readonly parameters: typepack?,
            readonly results: typepack?
        },
        readonly elements: comptime function(value: type): {type},
        readonly fields: comptime function(value: type): {{
            name: string,
            read: type?,
            write: type?
        }},
        readonly readKeys: comptime function(value: type): {type},
        readonly writeKeys: comptime function(value: type): {type},
        readonly readAt: comptime function(value: type, key: type): type,
        readonly writeAt: comptime function(value: type, key: type): type,
        readonly error: comptime function(message: string): never
    },

    --- Compiler-only derive inspection and closed forwarding recipes.
    derive: nupp.derive,

    --- Semantic type reflection and reflection-driven field codecs.
    reflect: nupp.reflect,

    --- Size in bytes under the build target's declared C ABI.
    sizeof: function(typeName: any): integer,

    --- Alignment in bytes under the build target's declared C ABI.
    alignof: function(typeName: any): integer,

    --- Byte offset of one field under the build target's declared C ABI.
    offsetof: function(typeName: any, fieldName: string): integer,

    --- Compiler-internal materialization conformance surface.
    --- @internal
    __materializationTest: nupp.__MaterializationTestAPI
}

--- What one poll did, discriminated by `kind`.
---
--- The four answers are `"prepared"`, when a patch was staged and committed and
--- `generation` is now the live one; `"no-change"`, when no watched input moved;
--- `"diagnostics"`, when the change did not check and the running generation stands;
--- and `"restart-required"`, when the change is well-typed but outside what a live
--- process can take.
---
--- The fields past `kind` are the ones that answer carries, so read them after
--- branching on it rather than before.
--- @internal
record nupp.HotReloadPoll
    kind: string

    --- Present on `"prepared"` and `"no-change"`. On the first it is the generation
    --- now running; on the second, the one that stayed.
    generation: integer?

    --- The published patch chunk, on `"prepared"`.
    patch: string?

    --- What a `"prepared"` answer was prepared against.
    baseGeneration: integer?

    --- Why the change was refused, on `"diagnostics"` and `"restart-required"`.
    diagnostics: {any}?

    --- Which boundary refused it, where a restart answer could name one.
    reason: any
end

--- Cooperative hot reload installed only while `nupp run --watch` is active.
--- @internal
record nupp.HotReload
    --- Returns the currently committed implementation generation.
    generation: nosuspend function(): integer

    --- Detects source edits and commits a compatible patch at this host boundary.
    ---
    --- Branch on `kind`: a poll that published reports `"prepared"`, one that found
    --- nothing reports `"no-change"`, and the two refusals are told apart by whether
    --- restarting is what it would take.
    poll: function(): nupp.HotReloadPoll
end

--- A compile-time-only graph handle used by the compiler's materialization tests.
--- @internal
record nupp.__MaterializationBlueprint
    link: function(
        self: nupp.__MaterializationBlueprint,
        child: nupp.__MaterializationBlueprint
    ): nupp.__MaterializationBlueprint
end

--- A compile-time-only factory handle used by the compiler's conformance provider.
--- @internal
record nupp.__MaterializationFactoryBlueprint
end

--- The runtime value produced by the compiler's materialization test provider.
--- @internal
record nupp.__MaterializedTest
    value: integer
    nodes: integer
end

--- The ordinary runtime input accepted by the conformance provider's factory.
--- @internal
record nupp.__MaterializationTestInput
    value: integer
end

--- Compiler-internal constructors for the materialization conformance provider.
--- @internal
record nupp.__MaterializationTestAPI
    node: function(value: integer): nupp.__MaterializationBlueprint
    factory: function(): nupp.__MaterializationFactoryBlueprint
end

--- Generates checked members on a declaration while that declaration is checked.
---
--- `@derive(Provider, ...)` names providers on a `record` or `struct`. Each one reads
--- an immutable semantic view of the declaration and returns a closed recipe; the
--- compiler generates members from that recipe and checks them the way it checks
--- written ones. This is a declaration-augmentation phase rather than a text macro. A
--- provider adds no imports, top-level declarations, modules, or independently
--- nameable types, and it observes no tokens, source positions, comments, or another
--- provider's output.
---
--- Two providers ship with the compiler and cross the same boundary a package
--- provider does: `Debug` and `JSON`.
---
--- #### Derive the shipped providers
---
--- ```nupp
--- @derive(nupp.derive.Debug, nupp.derive.JSON)
--- local record Settings
---     host: string = "localhost"
---     port: integer = 8080
--- end
---
--- local settings = new Settings()
--- assert(settings:debug() == 'Settings { host = "localhost", port = 8080 }')
--- ```
---
--- #### Write a package provider
---
--- A provider is an exported, nongeneric `comptime function` whose signature names the
--- one interface it implements. `Info` describes the owner, `implement` returns the
--- recipe, and a consumer applies the resolved export rather than a runtime function
--- value. Applying it also claims that interface.
---
--- ```nupp:static
--- local M = {}
---
--- interface M.Named
---     named: function(self): string
--- end
---
--- function M.nameValue(value: string): string
---     return "name=" .. value
--- end
---
--- comptime function M.derive(info: nupp.derive.Info): nupp.derive.Result<M.Named>
---     local field = info.fields[1]
---     if not field or field.name ~= "name" then
---         return nupp.derive.error("Named needs a first field named name", info.reference)
---     end
---
---     return nupp.derive.implement{
---         methods = {
---             named = nupp.derive.forward{
---                 helper = nupp.derive.helper(M, "nameValue"),
---                 arguments = {nupp.derive.field(field)},
---             },
---         },
---     }
--- end
---
--- @derive(M.derive)
--- record M.User
---     name: string
--- end
---
--- local user = new M.User(name = "ada")
--- assert(user:named() == "name=ada")
---
--- return M
--- ```
---
--- #### What a recipe may say
---
--- The interface owns every generated signature, so a recipe chooses only which runtime
--- function stands behind a requirement and which values reach it. `forward` names one
--- ordinary exported Nupp function and a closed argument list built from `receiver`,
--- `argument`, `field`, `constant`, and `array`. There are no nested calls, operators,
--- branches, loops, assignments, or provider-chosen signatures, so behavior stays in
--- ordinary type-checked Nupp rather than in a macro IR, and the generated call is
--- checked against the helper's declaration the way any other call is.
---
--- `forward.v1` fills only bodyless, unoverloaded callable requirements, and cannot
--- replace an interface default. A provider that refuses a declaration returns `error`
--- rather than raising.
---
--- Providers run inside the bounded comptime worker, once per owner rather than once
--- per generic instantiation, and a recipe is memoized on the `Info` fingerprint.
--- `claims` asks whether a type already writes or requests an interface, which lets
--- mutually recursive derives plan without depending on evaluation order.
record nupp.derive
    --- A comptime-only provider symbol accepted by `@derive`.
    ---
    --- A shipped provider is one of the three values below; a package provider is the
    --- `comptime function` a module exports. Neither survives into the program.
    record Provider
    end

    --- Generates `debug(self): string` and `nupp.Debug` conformance, rendering the
    --- declaration's own fields in declaration order.
    ---
    --- `@debug(redact = true)` keeps a field's name and hides its value, which is what
    --- a
    --- secret wants; `@debug(skip = true)` removes the field from the output entirely.
    ---
    --- ```nupp
    --- @derive(nupp.derive.Debug)
    --- local record Credentials
    ---     user: string
    ---     @debug(redact = true)
    ---     password: string
    --- end
    ---
    --- local credentials = new Credentials(user = "ada", password = "hunter2")
    --- assert(credentials:debug() == 'Credentials { user = "ada", password = <redacted> }')
    --- ```
    Debug: Provider

    --- Generates `toJSON`, a static `fromJSON(text): T?, string?`, a `fieldCodec`, and
    --- `nupp.data.json.JSONEncodable` conformance.
    ---
    --- Encoding is deterministic: fields follow declaration order and string map keys
    --- sort by byte order, so one value always produces the same bytes. A decode error
    --- names the path that failed rather than saying the document was bad.
    ---
    --- ```nupp
    --- @derive(nupp.derive.JSON)
    --- local record User
    ---     @json(name = "user_id")
    ---     id: integer
    ---     name: string
    --- end
    ---
    --- local user = new User(id = 7, name = "ada")
    --- assert(user:toJSON() == '{"user_id":7,"name":"ada"}')
    ---
    --- local decoded, failure = User.fromJSON('{"name": "ada"}')
    --- assert(decoded == nil and failure == '$.user_id: required field is absent')
    --- ```
    JSON: Provider

    --- Semantic configuration visible to providers as `Info` annotations.
    ---
    --- Each of these is the checked shape of one field annotation. A provider reads
    --- what was written from `Field.annotations` or `Info.annotations`; the shipped
    --- providers read the same projection rather than consulting a second planner.
    --- The checked shape of `@json`, written on a record or on one of its fields.
    interface JSONOptions
        --- What decoding does with a key the record does not declare. Written on the
        --- record, and `reject` when omitted.
        unknown: ("reject" | "ignore")?

        --- The key this field encodes to and decodes from.
        name: string?

        --- Removes the field from both directions. Requires a default.
        omit: boolean?

        --- Omits nil, false, empty strings, and empty tables when encoding. Encoding
        --- only: a field left out of the output is still required coming back in.
        omitEmpty: boolean?
    end

    --- The checked shape of `@debug`, written on a field.
    interface DebugOptions
        --- Removes the field from the rendered output entirely.
        skip: boolean?

        --- Keeps the field's name and renders its value as `<redacted>`.
        redact: boolean?
    end

    --- An opaque reference which a provider may attach to a diagnostic.
    ---
    --- Obtained from `Info.reference` for the declaration or `Field.reference` for one
    --- field, and accepted only by `error`. It carries no filename, line, or column: a
    --- provider says which part of the declaration is at fault and the compiler decides
    --- where to point.
    record Reference
    end

    --- One written stored field in the immutable derive input projection.
    ---
    --- Fields arrive in declaration order. A generated member never reaches one by
    --- name; pass this value to `field` to read it.
    record Field
        --- The name as written.
        readonly name: string

        --- Whether the field can be read, and so whether `field` admits it.
        readonly readable: boolean

        --- Whether the field can be written.
        readonly writable: boolean

        --- A transported handle for the read type, or nil for a write-only field.
        readonly readType: any?

        --- A transported handle for the write type, or nil for a read-only field.
        readonly writeType: any?

        --- Whether omission during construction supplies a declaration-owned default.
        readonly hasDefault: boolean

        --- The source-free constant default value. Read only when `hasDefault` is true.
        readonly defaultValue: any

        --- The field's typed annotations in source order, `@json` and `@debug` among
        --- them.
        readonly annotations: {nupp.reflect.Annotation}

        --- Points this provider's `error` at this field.
        readonly reference: Reference
    end

    --- The immutable semantic view passed to a `comptime function` provider.
    ---
    --- One `Info` describes one owner for one provider, and is built before any
    --- provider's output is merged, so two providers on the same declaration see the
    --- same thing whichever order they run in. A generic owner is projected once rather
    --- than per instantiation, and a type parameter exposes its bound, or `unknown`, so
    --- a provider cannot specialize for arguments a later instantiation supplies.
    record Info
        --- The projection's schema version, currently 1.
        readonly schema: integer

        --- What the owner was declared as: `record`, `struct`, or `interface`.
        readonly kind: string

        --- The owner's declared name.
        readonly name: string

        --- How the declaration is bound: `local`, `module`, `global`, or `nested`.
        readonly visibility: string

        --- The stable identity of the provider being run.
        readonly providerIdentity: string

        --- The stable identity of the owning declaration.
        readonly ownerIdentity: string

        --- A transported handle for the owner's type, accepted by `claims`.
        readonly ownerType: any

        --- A transported handle for the one interface this provider implements.
        readonly interfaceType: any

        --- The written stored fields, in declaration order.
        readonly fields: {Field}

        --- The owner's own typed annotations, in source order.
        readonly annotations: {nupp.reflect.Annotation}

        --- Whether the declaration writes a constructor.
        readonly hasConstructor: boolean

        --- Points this provider's `error` at the declaration as a whole.
        readonly reference: Reference

        --- A digest of everything above. Two owners with one fingerprint share one
        --- evaluation, so a provider must decide from `Info` and nothing else.
        readonly fingerprint: string
    end

    --- One value a generated call passes.
    ---
    --- Built by `receiver`, `entry`, `argument`, `field`, `constant`, or `array`.
    --- The compiler owns it: a provider may hold one and place it in an argument
    --- list, and nothing else.
    record Argument
    end

    --- An ordinary exported Nupp function a generated member calls, from `helper`.
    ---
    --- The module owning it becomes a runtime dependency of the consumer, even when the
    --- comptime provider itself erases.
    record RuntimeHelper
    end

    --- One requirement's implementation, from `forward`, to be placed in `implement`
    --- under the name of the requirement it fills.
    record Forward
    end

    --- A generated member with a comptime-built function signature and forward
    --- recipe. Use this when the provider declares a member that is not already an
    --- interface requirement.
    record Member
    end

    --- What a provider returns: the recipe implementing interface `I`.
    ---
    --- `I` is the interface the provider implements, or `any` when every generated
    --- member supplies its own signature. Writing an interface in the return type is
    --- how `@derive` knows which contract applying the provider claims. Produce one
    --- with `implement`, or refuse the declaration with `error`. The compiler owns it
    --- and there is nothing on it to read: what it carries crosses the comptime
    --- boundary as a versioned recipe the compiler validates.
    ---
    --- @typearg I the interface this provider implements, or `any`
    record Result<I>
    end

    --- Returns forwarding implementations. `methods` fills instance members and
    --- `statics` fills static members.
    ---
    --- Both are keyed by member name. A `Forward` fills a bodyless, unoverloaded
    --- callable requirement on the provider's interface; a `Member` supplies a new
    --- member's function signature and forwarding recipe. Generating a member that
    --- another provider on the same owner already generates is refused.
    ---
    --- @param specification a table with optional `methods` and `statics` maps
    --- @return the recipe, as this provider's `Result<I>`
    implement: function(specification: any): any

    --- Reads one immutable filesystem input admitted to this provider invocation.
    ---
    --- The path must be a string literal in the provider's checked source. It resolves
    --- from the consumer project root, becomes an incremental query dependency, and is
    --- included in the provider recipe fingerprint. Watch mode therefore observes the
    --- file and rechecks only modules that consume the provider.
    ---
    --- @param path project-relative path written as a literal
    --- @return the file's bytes
    file: function(path: string): string

    --- Refuses the declaration with a diagnostic instead of returning a recipe.
    ---
    --- The reference decides what the diagnostic points at: `Info.reference` for the
    --- declaration, or the `Field.reference` of the field that made the recipe
    --- impossible. Returning this is how a provider fails; raising is a provider fault.
    ---
    --- @param message what the consumer is told
    --- @param reference which part of the declaration is at fault
    --- @param code the diagnostic code, defaulting to `NUPP2810`
    --- @return the refusal, as this provider's `Result<I>`
    error: function(message: string, reference: Reference?, code: string?): any

    --- Implements one requirement by calling one runtime helper.
    ---
    --- `helper` names the function and `arguments` is the closed list it receives, in
    --- order. The interface owns the resulting signature, and the generated call is
    --- checked against the helper's declaration for types, ownership, effects, and its
    --- suspension contract.
    ---
    --- @param specification a table with `helper` and `arguments`
    --- @return the implementation, to place in `implement`
    forward: function(specification: any): Forward

    --- Declares a generated member's function signature and forwarding recipe.
    ---
    --- @param specification a table with `signature`, optional parameter names, and
    --- a `forward` recipe
    --- @return the member recipe, to place in `implement`
    member: function(specification: any): Member

    --- Names an ordinary exported Nupp function to forward to.
    ---
    --- Runtime behavior stays in the language: helpers are checked at their own
    --- declarations, and a generic helper is refused by `forward.v1`.
    ---
    --- @param module the module value holding the function
    --- @param name the name it is exported under
    --- @return the helper handle
    helper: function(module: any, name: string): RuntimeHelper

    --- Passes the generated method's receiver.
    ---
    --- @return the argument recipe
    receiver: function(): Argument

    --- Passes the record's registered derive entry.
    ---
    --- @return the argument recipe
    entry: function(): Argument

    --- Passes one parameter of the generated method, under the name the interface
    --- requirement declares for it.
    ---
    --- @param name the parameter's declared name
    --- @return the argument recipe
    argument: function(name: string): Argument

    --- Reads one stored field of the receiver directly. The field must be readable.
    ---
    --- @param field one of `Info.fields`
    --- @return the argument recipe
    field: function(field: Field): Argument

    --- Embeds a bounded quotable value.
    ---
    --- A table-shaped constant is rebuilt for every call, so mutation by one invocation
    --- cannot reach the next.
    ---
    --- @param value the value to embed
    --- @return the argument recipe
    constant: function(value: any): Argument

    --- Builds a fresh array from argument recipes, once per call.
    ---
    --- @param arguments the element recipes, in order
    --- @return the argument recipe
    array: function(arguments: {Argument}): Argument

    --- Asks whether a type writes or requests an interface.
    ---
    --- The answer does not depend on whether that type's own providers have run, so
    --- mutually recursive derives can plan against one another.
    ---
    --- @param subject a type handle, such as a `Field.readType`
    --- @param interface a type handle, such as `Info.interfaceType`
    --- @return whether `subject` claims `interface`
    claims: function(subject: any, interface: any): boolean
end

--- Compiles textual parsing-expression grammars into reusable matchers.
---
--- `nupp.peg` has one construction operation, `compile`. It accepts the same
--- expression language during compilation and at runtime. A constant call inside a
--- `comptime` block is validated and materialized into the program; a call with a
--- runtime string parses and caches the grammar when the program runs. Neither form
--- requires a separately installed LPeg: its resolved native effect asks the build
--- for a host that supplies LPeg 1.1.
---
--- PEGs use ordered choice. `first / second` tries `second` only when `first` fails,
--- and a later failure may backtrack into an earlier choice. Sequence is written by
--- placing expressions beside one another. The usual precedence, from tightest to
--- loosest, is primary expressions, repetition and actions, predicates, sequence,
--- then `/`.
---
--- #### Expression quick reference
---
--- | Expression | Meaning |
--- | --- | --- |
--- | `'text'` or `"text"` | the exact bytes in `text` |
--- | `.` | any one byte |
--- | `[a-z_]` | one byte from a class or range |
--- | `[^0-9]` | one byte outside a class |
--- | `%a`, `%d`, `%s`, `%w`, `%x` | ASCII letter, digit, space, alphanumeric, or hex
--- byte; any other `%name` reads a definition |
--- | `p q` | `p` followed by `q` |
--- | `p / q` | ordered choice: try `p`, then `q` |
--- | `p*`, `p+`, `p?` | zero or more, one or more, or optional `p` |
--- | `p^4`, `p^+4`, `p^-4` | exactly, at least, or at most four repetitions |
--- | `&p`, `!p` | require `p`, or require that `p` fails, without consuming input |
--- | `{ p }` | capture the substring consumed by `p` |
--- | `{}` | capture the current 1-based byte position |
--- | `{| p |}` | collect all captures produced by `p` into an array |
--- | `{: name: p :}` | group captures under `name`; omit `name:` for an anonymous group
--- |
--- | `{~ p ~}` | substitute captured text into the substring consumed by `p` |
--- | `=name` | match the text previously captured by named group `name` |
--- | `p -> {}` | collect `p`'s captures in a table |
--- | `p -> n`, `p -> 'text'` | select capture `n`, or format captures into text |
--- | `p -> name` | transform `p` through definition `name` |
--- | `p => name` | invoke match-time definition `name` |
--- | `p >> name`, `p ~> name` | accumulate captures, or fold them left |
--- | `name <- p` | define a grammar rule; the first rule is the start rule |
--- | `name` or `<name>` | refer to a rule inside a grammar |
--- | `!.` | require end of input |
---
--- Whitespace separates expressions and is otherwise ignored. `--` starts a comment
--- extending to the end of the line. Quoted strings contain their bytes literally;
--- this grammar notation does not process backslash escapes. Use the other quote
--- character when a literal needs one kind of quote.
---
--- #### Recognize a complete identifier
---
--- ```nupp
--- const Identifier: nupp.peg.Peg<integer> = comptime do
---     return nupp.peg.compile([[
---         [a-zA-Z_] [a-zA-Z_0-9]* !.
---     ]])
--- end
---
--- assert(Identifier("name_2") == 7)
--- assert(Identifier("2wrong") == nil)
--- ```
---
--- A successful recognizer returns the byte position immediately after the match.
--- Add `!.` when the pattern must consume the complete subject. Without it, a prefix
--- match is successful.
---
--- #### Capture and convert a value
---
--- ```nupp
--- local record NumberDefinitions
---     number: function(string): integer
--- end
---
--- const NumberFactory:
---     function(NumberDefinitions): nupp.peg.Peg<integer> = comptime do
---     return nupp.peg.compile("[0-9]+ -> number !.")
--- end
---
--- local Number = NumberFactory(new NumberDefinitions {
---     number = function(text: string): integer
---         return assert(tonumber(text)) as integer
---     end,
--- })
--- assert(Number("42") == 42)
--- ```
---
--- Static grammars with definitions materialize as factories because runtime values
--- cannot be captured during `comptime`. Runtime grammars instead receive them through
--- `CompileOptions.definitions`.
record nupp.peg
    --- The implementation selected after the grammar has been parsed.
    ---
    --- `auto` is the default. It emits straight-line Lua for the small matcher shapes
    --- where Nupp is faster and lowers every other grammar to native LPeg. `lpeg`
    --- disables specialization and always uses LPeg. Both paths share one typed
    --- matcher shell and identical capture semantics.
    type Backend = 'auto' | 'lpeg'

    --- A legacy substring transformation callback.
    ---
    --- Prefer `Definitions`: LPeg `re` gives `->`, `=>`, `>>`, and `~>` distinct
    --- callback contracts. This alias remains for source compatibility with Nupp's
    --- earlier action-only grammar surface.
    type Action = function(string): any

    --- Legacy runtime transformation callbacks indexed by grammar name.
    ---
    --- Prefer `Definitions`. Every grammar slot must be present and unknown names are
    --- rejected. Static grammars use a precisely typed factory record instead.
    type Actions = {[string]: Action}

    --- Values referenced by LPeg `re` expressions.
    ---
    --- A `%name` primary uses a string, non-negative byte count, or boolean as a
    --- pattern. `p -> name` accepts the same function, table, string, or capture
    --- number transformations as LPeg. `=>`, `>>`, and `~>` require functions with
    --- their corresponding match-time, accumulator, and fold contracts.
    type Definitions = {[string]: any}

    --- Controls grammar compilation.
    ---
    --- These options are deliberately small. At runtime, grammar source plus
    --- `backend` selects specialization or native LPeg; definitions are bound to the
    --- returned matcher and are not part of the grammar's compile-time type.
    type CompileOptions = {
        --- Values named by `%name`, `-> name`, `=> name`, `>> name`, or `~> name`.
        definitions: Definitions?,

        --- Deprecated alias for `definitions` retained for existing Nupp grammars.
        actions: Actions?,

        --- Matcher implementation, `auto` when omitted.
        backend: Backend?
    }

    --- A compiled matcher whose result pack is chosen by its declaration.
    --- Generic adapters forward `R...` without collecting it into a table or tuple.
    interface Matcher<R...>
        match: function(self, subject: string, init: integer?): ((R...) | (nil))
        find: function(self, subject: string, init: integer?): ((integer, integer, R...) | (nil, nil))
        isMatch: function(self, subject: string, init: integer?): boolean
        forEachMatch: function(
            self,
            subject: string,
            visitor: function(first: integer, nextPosition: integer, R...),
            init: integer?
        ): integer
        replace: function(
            self,
            subject: string,
            replacement: string | function(first: integer, nextPosition: integer, R...): string,
            init: integer?
        ): string
        replaceAll: function(
            self,
            subject: string,
            replacement: string | function(first: integer, nextPosition: integer, R...): string,
            init: integer?
        ): string

        metamethod __call: function(self, subject: string, init: integer?): ((R...) | (nil))
    end

    --- A compiled and reusable parsing-expression grammar.
    ---
    --- `R...` is the grammar's native Lua result pack. A recognizer or `{}` position
    --- capture contributes `integer`, `{ p }` contributes `string`, and adjacent
    --- captures contribute adjacent results. No tuple or table is allocated merely
    --- because a grammar returns several values. An explicit `{| ... |}` table
    --- capture still returns one table because the grammar requested one.
    ---
    --- Matchers are immutable and callable. `peg(subject, init)` is exactly
    --- `peg:match(subject, init)`.
    record Peg<R...> is Matcher<R...>

        --- Matches `subject` beginning at a 1-based byte position.
        ---
        --- The default `init` is 1. A negative position counts from the end in the
        --- same way as Lua string operations; positions before the beginning clamp to
        --- 1, and positions after `#subject + 1` fail. Success returns the grammar's
        --- capture or, for a recognizer, the next byte position. Failure returns nil.
        ---
        --- ```nupp
        --- local Word = nupp.peg.compile("{ [a-z]+ }")
        --- assert(Word:match("one two", 5) == "two")
        --- assert(Word("123") == nil)
        --- ```
        --- @param self the compiled grammar
        --- @param subject bytes to match
        --- @param init 1-based starting byte position, 1 when omitted
        --- @return the grammar result pack, or nil when the match fails
        match: function(self, subject: string, init: integer?): ((R...) | (nil))

        --- Finds the first match at or after `init` without allocating match metadata.
        ---
        --- Success returns `first, next, R...`. The byte range is half-open:
        --- `[first, next)`, so an empty match has `first == next`. The trailing
        --- values are the ordinary grammar results; for a recognizer the result is the
        --- same next-byte
        --- position. Failure returns nil positions. Test `first`, rather than
        --- `value`, because an action may successfully return nil or false.
        ---
        --- ```nupp
        --- local Word = nupp.peg.compile("{ [a-z]+ }")
        --- local first, nextPosition, value = Word:find("123 hello")
        --- assert(first == 5 and nextPosition == 10 and value == "hello")
        --- ```
        --- @param self the compiled grammar
        --- @param subject bytes to search
        --- @param init 1-based first byte position to try, 1 when omitted
        --- @return first byte, exclusive next byte, and grammar results; nil on failure
        find: function(self, subject: string, init: integer?): ((integer, integer, R...) | (nil, nil))

        --- Reports whether the grammar matches anywhere at or after `init`.
        ---
        --- Unlike `match`, this searches successive 1-based byte positions. The
        --- default `init` is 1, and negative and out-of-range positions follow the
        --- same rules as `match`. The position after the final byte is searched too,
        --- so a grammar that accepts an empty suffix can match there.
        ---
        --- ```nupp
        --- local Digits = nupp.peg.compile("[0-9]+")
        --- assert(Digits:isMatch("room 42"))
        --- assert(not Digits:isMatch("room", 2))
        --- ```
        --- @param self the compiled grammar
        --- @param subject bytes to search
        --- @param init 1-based first byte position to try, 1 when omitted
        isMatch: function(self, subject: string, init: integer?): boolean

        --- Visits every non-overlapping match at or after `init` without allocating
        --- match records or an iterator closure.
        ---
        --- The visitor receives `first, next, R...` in the same form as `find`.
        --- Consuming matches resume at `next`; an empty match resumes one byte after
        --- `first`, preventing an empty grammar from stalling. The position after the
        --- final byte is still visited when it matches. Returning from the visitor
        --- does not stop iteration.
        ---
        --- ```nupp
        --- local Word = nupp.peg.compile("{ [a-z]+ }")
        --- local seen: {string} = {}
        --- local count = Word:forEachMatch("one, two", function(_, _, word: string)
        ---     seen[#seen + 1] = word
        --- end)
        --- assert(count == 2 and seen[2] == "two")
        --- ```
        --- @param self the compiled grammar
        --- @param subject bytes to search
        --- @param visitor called once for each non-overlapping match
        --- @param init 1-based first byte position to try, 1 when omitted
        --- @return the number of matches visited
        forEachMatch: function(
            self,
            subject: string,
            visitor: function(first: integer, nextPosition: integer, R...),
            init: integer?
        ): integer

        --- Replaces the first match at or after `init`.
        ---
        --- A string replacement is literal. A callback receives `first, next, R...`
        --- and returns the replacement bytes. When nothing matches, the original
        --- string is returned. Empty matches insert without consuming a byte.
        ---
        --- ```nupp
        --- local Digits = nupp.peg.compile("[0-9]+")
        --- assert(Digits:replace("room 42, floor 3", "#") ==
        ---     "room #, floor 3")
        --- ```
        --- @param self the compiled grammar
        --- @param subject bytes to search and copy
        --- @param replacement literal bytes or a typed replacement callback
        --- @param init 1-based first byte position to try, 1 when omitted
        --- @return the replaced string
        replace: function(
            self,
            subject: string,
            replacement: string | function(first: integer, nextPosition: integer, R...): string,
            init: integer?
        ): string

        --- Replaces every non-overlapping match at or after `init`.
        ---
        --- Matching resumes at the exclusive end of each consuming match. After an
        --- empty match it advances one byte and preserves that skipped byte in the
        --- output, so an empty grammar inserts before every remaining byte and once at
        --- the end. Text before `init` is copied unchanged.
        ---
        --- ```nupp
        --- local Digits = nupp.peg.compile("[0-9]+")
        --- assert(Digits:replaceAll("room 42, floor 3", "#") ==
        ---     "room #, floor #")
        --- ```
        --- @param self the compiled grammar
        --- @param subject bytes to search and copy
        --- @param replacement literal bytes or a typed replacement callback
        --- @param init 1-based first byte position to try, 1 when omitted
        --- @return the replaced string
        replaceAll: function(
            self,
            subject: string,
            replacement: string | function(first: integer, nextPosition: integer, R...): string,
            init: integer?
        ): string

        metamethod __call: function(self, subject: string, init: integer?): ((R...) | (nil))
    end

    --- Compiles an LPeg-re-style byte grammar at compile time or runtime.
    ---
    --- A literal grammar produces a precise `Peg<R...>` at either phase for ordinary
    --- recognition and captures. A dynamic grammar string returns `Peg<...any>`. A
    --- static grammar referring to definitions needs an explicitly typed factory,
    --- because runtime values cannot be captured at `comptime`.
    ---
    --- ```nupp
    --- local Words = nupp.peg.compile(
    ---     "{| { [a-z]+ } (',' { [a-z]+ })* |} !."
    --- )
    --- local values = assert(Words("red,green,blue")) as {string}
    --- assert(values[2] == "green")
    ---
    --- local General = nupp.peg.compile("[0-9]+ !.", {backend = "lpeg"})
    --- assert(General("123") ~= nil)
    --- ```
    --- @param source grammar expression or rule definitions
    --- @param options runtime definitions and backend selection
    --- @return the compiled reusable matcher
    compile: function(source: string, options: CompileOptions?): Peg<...any>
end

--- Semantic type reflection and reflection-driven field codecs.
---
--- Call the namespace with a concrete type inside `comptime` to obtain an immutable,
--- target-independent descriptor. `fieldCodec` materializes the stored fields of a
--- reflected record into a keyed runtime codec.
record nupp.reflect
    --- One checked member supplied to a reflected typed annotation.
    ---
    --- `value` is present for `kind = "value"`; `type` is an index into the owning
    --- `Info.types` graph for `kind = "type"`. `kind = "nil"` preserves an explicitly
    --- supplied nil without pretending an absent table field contains it.
    record AnnotationArgument
        readonly name: string
        readonly kind: "value" | "nil" | "type"
        readonly value: any?
        readonly type: integer?
    end

    --- One typed annotation application, retaining source order.
    record Annotation
        readonly name: string
        readonly arguments: {AnnotationArgument}
    end

    --- One stored field projected directly from the reflected root type.
    record Field
        readonly name: string
        readonly kind: string
        readonly typeName: string?
        readonly type: integer?
        readonly readable: boolean
        readonly writable: boolean
        readonly hasDefault: boolean
        readonly defaultValue: any
        readonly annotations: {Annotation}
    end

    --- One named or positional edge in the indexed semantic type graph.
    record Entry
        readonly name: string?
        readonly type: integer?
        readonly read: integer?
        readonly write: integer?
        readonly readable: boolean?
        readonly writable: boolean?
        readonly hasDefault: boolean?
        readonly defaultValue: any
        readonly mode: string?
        readonly bound: integer?
        readonly answer: integer?
        readonly default: boolean?
        readonly annotations: {Annotation}?
        readonly [string]: any
    end

    --- One node in an `Info` semantic type graph.
    record Node
        readonly kind: string
        readonly name: string?
        readonly nominal: boolean?
        readonly annotations: {Annotation}?
        readonly fields: {Entry}?
        readonly staticFields: {Entry}?
        readonly metamethods: {Entry}?
        readonly nestedTypes: {Entry}?
        readonly associatedTypes: {Entry}?
        readonly members: {integer}?
        readonly parameters: {Entry}?
        readonly returns: {integer}?
        readonly typeParameters: {integer}?
        readonly typeBounds: {integer}?
        readonly packParameters: {integer}?
        readonly constParameters: {integer}?
        readonly parameterKinds: {string}?
        readonly typeArguments: {integer}?
        readonly packArguments: {integer}?
        readonly constArguments: {integer}?
        readonly supertypes: {integer}?
        readonly element: integer?
        readonly body: integer?
        readonly of: integer?
        readonly origin: integer?
        readonly noReturn: boolean?
        readonly noYield: boolean?
        readonly [string]: any
    end

    --- One top-level stored struct field available as a SoA column.
    record SoAField
        readonly name: string
        readonly identity: string
        readonly ordinal: integer
        readonly type: integer?
        readonly ctype: string?
        readonly eligible: boolean
    end

    --- Target-independent semantic inputs to SoA storage derivation.
    record SoAInfo
        readonly schema: integer
        readonly eligible: boolean
        readonly reason: string?
        readonly fields: {SoAField}
    end

    --- An immutable compile-time description of one resolved semantic type.
    record Info
        readonly schema: integer
        readonly root: integer
        readonly types: {Node}
        readonly kind: string
        readonly name: string
        readonly qualifiedName: string
        readonly fields: {Field}
        readonly annotations: {Annotation}
        readonly soa: SoAInfo
        readonly fingerprint: string
    end

    --- An opaque field-codec recipe returned inside `comptime`.
    record FieldCodecBlueprint
    end

    --- A keyed runtime codec materialized from a reflected record.
    record FieldCodec<T>
        encode: function(self, value: T): {[string]: any}
        decode: function(self, value: {[string]: any}): (T?, string?)
        fingerprint: string
    end

    --- Reflects a concrete type for use inside a `comptime` block.
    metamethod __call: comptime function(self, typeName: any): Info

    --- Builds a keyed field-codec recipe from a reflected record.
    fieldCodec: comptime function(info: Info): FieldCodecBlueprint
end

--- Internal typed schema for the compiler-owned @deprecated annotation.
--- @internal
interface nupp.__DeprecatedAnnotation
    --- Why callers should stop using the API.
    reason: string?

    --- The API spelling callers should migrate to.
    replacement: string?
end

--- Exact internal cleanup policies for the prelude's resource interfaces.
const __nuppDestroyByteView: nosuspend function(takes value: nupp.io.ByteView): nil

const __nuppDestroyReader: nosuspend function(takes value: nupp.io.Reader): nil
const __nuppDestroyWriter: nosuspend function(takes value: nupp.io.Writer): nil
const __nuppDestroyBuffer: nosuspend function(takes value: nupp.io.Buffer): nil
const __nuppDestroyFile: nosuspend function(takes value: nupp.io.Files.File): nil
const __nuppDestroyTemporaryPath: nosuspend function(takes value: nupp.io.Files.TemporaryPath): nil
const __nuppDestroyScalarReader: nosuspend function(takes value: nupp.io.ScalarReader): nil
const __nuppDestroyScalarWriter: nosuspend function(takes value: nupp.io.ScalarWriter): nil

--- Buffers, byte views, readers, writers, filesystem paths and URIs.
record nupp.io
    --- An immutable snapshot of bytes.
    interface ByteView
        --- Opens a reader over this snapshot.
        --- @param self this byte view
        --- @return the new reader
        newReader: function(self: ByteView): affine(Reader, __nuppDestroyReader)

        --- Reports the number of bytes in this snapshot.
        --- @param self this byte view
        --- @return the byte length
        length: function(self: ByteView): integer

        --- Copies all bytes into a string.
        --- @param self this byte view
        --- @return the copied bytes
        getString: function(self: ByteView): string

        --- Retains an immutable subrange of this snapshot.
        --- @param self this byte view
        --- @param offset the zero-based start, or zero when omitted
        --- @param count the number of bytes, or the rest of the view when omitted
        --- @return the retained subrange
        view: function(self: ByteView, offset: integer?, count: integer?): affine(ByteView, __nuppDestroyByteView)

        --- Reports whether this snapshot has been released.
        --- @param self this byte view
        --- @return whether the view is released
        isReleased: function(self: ByteView): boolean

        --- Releases this snapshot as an ownership terminal. Repeated calls are safe.
        --- @param self this byte view
        drop: nosuspend function(takes self: ByteView): nil

        --- Releases this snapshot and reports whether it succeeded.
        --- @param self this byte view
        --- @return whether the release succeeded
        --- @return a failure reason, when unsuccessful
        close: function(takes self: ByteView): (boolean, string?)
    end

    --- A forward-only byte source. An empty read or zero-byte readInto is EOF.
    interface Reader
        --- Reads the next bytes, returning an empty string at EOF.
        --- @param self this reader
        --- @param count the maximum number of bytes; non-positive values still read one
        --- @return the bytes, or nil on failure
        --- @return a failure reason, when unsuccessful
        read: function(self: Reader, count: integer): (string?, string?)

        --- Reads bytes into a buffer, returning zero at EOF.
        --- @param self this reader
        --- @param destination the buffer to append to or overwrite
        --- @param offset the zero-based destination offset, or zero when omitted
        --- @param count the maximum bytes to read, or 64 KiB when omitted
        --- @return the number of bytes read, or nil on failure
        --- @return a failure reason, when unsuccessful
        readInto: function(
            self: Reader,
            borrows destination: Buffer,
            offset: integer?,
            count: integer?
        ): (integer?, string?)

        --- Copies all remaining bytes into a writer.
        --- @param self this reader
        --- @param destination the writer to receive the bytes
        --- @return the number of bytes copied, or nil on failure
        --- @return a failure reason, when unsuccessful
        transferTo: function(self: Reader, borrows destination: Writer): (integer?, string?)

        --- Closes this reader as an ownership terminal. Repeated calls are safe.
        --- @param self this reader
        drop: nosuspend function(takes self: Reader): nil

        --- Closes this reader and reports whether it succeeded.
        --- @param self this reader
        --- @return whether the close succeeded
        --- @return a failure reason, when unsuccessful
        close: function(takes self: Reader): (boolean, string?)
    end

    --- A forward-only byte destination.
    interface Writer
        --- Writes a string of bytes.
        --- @param self this writer
        --- @param bytes the bytes to write
        --- @return whether the write succeeded
        --- @return a failure reason, when unsuccessful
        write: function(self: Writer, bytes: string): (boolean, string?)

        --- Copies bytes from a mutable buffer.
        --- @param self this writer
        --- @param source the source buffer
        --- @param offset the zero-based start, or zero when omitted
        --- @param count the number of bytes, or the rest of the buffer when omitted
        --- @return the number of bytes written, or nil on failure
        --- @return a failure reason, when unsuccessful
        writeFrom: function(
            self: Writer,
            borrows source: Buffer,
            offset: integer?,
            count: integer?
        ): (integer?, string?)

        --- Copies bytes from an immutable view.
        --- @param self this writer
        --- @param source the source byte view
        --- @param offset the zero-based start, or zero when omitted
        --- @param count the number of bytes, or the rest of the view when omitted
        --- @return the number of bytes written, or nil on failure
        --- @return a failure reason, when unsuccessful
        writeView: function(
            self: Writer,
            borrows source: ByteView,
            offset: integer?,
            count: integer?
        ): (integer?, string?)

        --- Flushes any buffered output.
        --- @param self this writer
        --- @return whether the flush succeeded
        --- @return a failure reason, when unsuccessful
        flush: function(self: Writer): (boolean, string?)

        --- Closes this writer as an ownership terminal. Repeated calls are safe.
        --- @param self this writer
        drop: nosuspend function(takes self: Writer): nil

        --- Closes this writer and reports whether it succeeded.
        --- @param self this writer
        --- @return whether the close succeeded
        --- @return a failure reason, when unsuccessful
        close: function(takes self: Writer): (boolean, string?)
    end

    --- An owned growable byte sequence. All offsets are zero-based.
    interface Buffer
        --- Opens a reader over a snapshot of the current bytes.
        --- @param self this buffer
        --- @return the new reader
        newReader: function(self: Buffer): affine(Reader, __nuppDestroyReader)

        --- Clears the buffer and opens a writer that targets it.
        --- @param self this buffer
        --- @return the new writer
        newWriter: function(self: Buffer): affine(Writer, __nuppDestroyWriter)

        --- Reports the logical byte length.
        --- @param self this buffer
        --- @return the byte length
        length: function(self: Buffer): integer

        --- Reports the reserved byte capacity.
        --- @param self this buffer
        --- @return the byte capacity
        capacity: function(self: Buffer): integer

        --- Removes every byte without discarding reserved capacity.
        --- @param self this buffer
        clear: function(self: Buffer)

        --- Reserves at least a byte capacity without changing the length.
        --- @param self this buffer
        --- @param minimum the minimum capacity
        ensureCapacity: function(self: Buffer, minimum: integer)

        --- Changes the byte length, truncating or zero-filling as needed.
        --- @param self this buffer
        --- @param length the new byte length
        resize: function(self: Buffer, length: integer)

        --- Copies a byte range into a string.
        --- @param self this buffer
        --- @param offset the zero-based start, or zero when omitted
        --- @param count the number of bytes, or the rest of the buffer when omitted
        --- @return the copied bytes
        getString: function(self: Buffer, offset: integer?, count: integer?): string

        --- Overwrites bytes at an offset, growing and zero-filling any gap.
        --- @param self this buffer
        --- @param bytes the bytes to write
        --- @param offset the zero-based start, or zero when omitted
        setString: function(self: Buffer, bytes: string, offset: integer?)

        --- Retains an immutable snapshot of a byte range.
        --- @param self this buffer
        --- @param offset the zero-based start, or zero when omitted
        --- @param count the number of bytes, or the rest of the buffer when omitted
        --- @return the retained byte view
        view: function(self: Buffer, offset: integer?, count: integer?): affine(ByteView, __nuppDestroyByteView)

        --- Reports whether this buffer has been released.
        --- @param self this buffer
        --- @return whether the buffer is released
        isReleased: function(self: Buffer): boolean

        --- Releases this buffer as an ownership terminal. Repeated calls are safe.
        --- @param self this buffer
        drop: nosuspend function(takes self: Buffer): nil

        --- Releases this buffer and reports whether it succeeded.
        --- @param self this buffer
        --- @return whether the release succeeded
        --- @return a failure reason, when unsuccessful
        close: function(takes self: Buffer): (boolean, string?)
    end

    --- A byte queue that consumes from its front, which is what LuaJIT's
    --- `string.buffer.Buffer` is. Naming the shape rather than that record keeps the
    --- prelude free of a require, and lets anything else with the same two operations
    --- stand in.
    interface ByteQueue
        metamethod __len: function(self): integer

        --- Consumes bytes from the front and returns them, or all of them when given
        --- no count.
        --- @param self this queue
        --- @param ... how many bytes each returned string takes
        --- @return the consumed bytes
        get: function(self: ByteQueue, ...: integer?): string
    end

    --- A cursor for sized integer and float reads over a byte source.
    ---
    --- Reads are host-endian, the only order LuaJIT ships. A format fixed to one
    --- byte order swaps explicitly.
    ---
    --- Every read consumes, and a short one raises rather than answering a reason:
    --- a scalar either landed whole or the source was not what the format said, and
    --- there is no partial value to hand back.
    interface ScalarReader
        --- Reports how many bytes are left, when the source can say. A reader over a
        --- stream cannot, and answers nil.
        --- @param self this reader
        --- @return the unread byte count, or nil when unknown
        remaining: function(self: ScalarReader): integer?

        --- Reports whether the source is exhausted.
        --- @param self this reader
        --- @return whether no bytes remain
        atEnd: function(self: ScalarReader): boolean

        --- Discards unread bytes. Raises when fewer remain.
        --- @param self this reader
        --- @param count how many bytes to discard
        --- @return this reader
        skip: function(self: ScalarReader, count: integer): ScalarReader

        --- Reads raw bytes. Raises when fewer remain.
        --- @param self this reader
        --- @param count how many bytes to read
        --- @return the bytes
        readBytes: function(self: ScalarReader, count: integer): string

        --- Reads one unsigned byte.
        --- @param self this reader
        --- @return the value
        readUint8: function(self: ScalarReader): uint32

        --- Reads one signed byte.
        --- @param self this reader
        --- @return the value
        readInt8: function(self: ScalarReader): int32

        --- Reads an unsigned 16-bit integer.
        --- @param self this reader
        --- @return the value
        readUint16: function(self: ScalarReader): uint32

        --- Reads a signed 16-bit integer.
        --- @param self this reader
        --- @return the value
        readInt16: function(self: ScalarReader): int32

        --- Reads an unsigned 32-bit integer.
        --- @param self this reader
        --- @return the value
        readUint32: function(self: ScalarReader): uint32

        --- Reads a signed 32-bit integer.
        --- @param self this reader
        --- @return the value
        readInt32: function(self: ScalarReader): int32

        --- Reads an unsigned 64-bit integer.
        --- @param self this reader
        --- @return the value
        readUint64: function(self: ScalarReader): uint64

        --- Reads a signed 64-bit integer.
        --- @param self this reader
        --- @return the value
        readInt64: function(self: ScalarReader): int64

        --- Reads a 32-bit float.
        --- @param self this reader
        --- @return the value
        readFloat32: function(self: ScalarReader): float

        --- Reads a 64-bit float.
        --- @param self this reader
        --- @return the value
        readFloat64: function(self: ScalarReader): number

        --- Closes this reader and its source as an ownership terminal. Repeated calls
        --- are safe.
        --- @param self this reader
        drop: nosuspend function(takes self: ScalarReader): nil

        --- Closes this reader and its source, reporting whether it succeeded.
        --- @param self this reader
        --- @return whether the close succeeded
        --- @return a failure reason, when unsuccessful
        close: function(takes self: ScalarReader): (boolean, string?)
    end

    --- A cursor for sized integer and float writes, appending to a destination.
    ---
    --- Writes are host-endian, matching [`ScalarReader`](#nupp.io.ScalarReader), and
    --- a destination that refuses one raises for the same reason a short read does.
    --- Every write answers the writer, so calls chain.
    interface ScalarWriter
        --- Appends bytes unchanged.
        --- @param self this writer
        --- @param bytes the bytes to append
        --- @return this writer
        writeBytes: function(self: ScalarWriter, bytes: string): ScalarWriter

        --- Writes one unsigned byte.
        --- @param self this writer
        --- @param value the value to write
        --- @return this writer
        writeUint8: function(self: ScalarWriter, value: uint32): ScalarWriter

        --- Writes one signed byte.
        --- @param self this writer
        --- @param value the value to write
        --- @return this writer
        writeInt8: function(self: ScalarWriter, value: int32): ScalarWriter

        --- Writes an unsigned 16-bit integer.
        --- @param self this writer
        --- @param value the value to write
        --- @return this writer
        writeUint16: function(self: ScalarWriter, value: uint32): ScalarWriter

        --- Writes a signed 16-bit integer.
        --- @param self this writer
        --- @param value the value to write
        --- @return this writer
        writeInt16: function(self: ScalarWriter, value: int32): ScalarWriter

        --- Writes an unsigned 32-bit integer.
        --- @param self this writer
        --- @param value the value to write
        --- @return this writer
        writeUint32: function(self: ScalarWriter, value: uint32): ScalarWriter

        --- Writes a signed 32-bit integer.
        --- @param self this writer
        --- @param value the value to write
        --- @return this writer
        writeInt32: function(self: ScalarWriter, value: int32): ScalarWriter

        --- Writes an unsigned 64-bit integer.
        --- @param self this writer
        --- @param value the value to write
        --- @return this writer
        writeUint64: function(self: ScalarWriter, value: uint64): ScalarWriter

        --- Writes a signed 64-bit integer.
        --- @param self this writer
        --- @param value the value to write
        --- @return this writer
        writeInt64: function(self: ScalarWriter, value: int64): ScalarWriter

        --- Writes a 32-bit float.
        --- @param self this writer
        --- @param value the value to write
        --- @return this writer
        writeFloat32: function(self: ScalarWriter, value: float): ScalarWriter

        --- Writes a 64-bit float.
        --- @param self this writer
        --- @param value the value to write
        --- @return this writer
        writeFloat64: function(self: ScalarWriter, value: number): ScalarWriter

        --- The buffer being appended to, when the destination is one. A writer given
        --- somebody else's writer answers nil, since the bytes are already gone.
        --- @param self this writer
        --- @return the destination buffer, or nil
        buffer: function(self: ScalarWriter): Buffer?

        --- Flushes the destination.
        --- @param self this writer
        --- @return whether the flush succeeded
        --- @return a failure reason, when unsuccessful
        flush: function(self: ScalarWriter): (boolean, string?)

        --- Closes this writer and its destination as an ownership terminal. Repeated
        --- calls are safe.
        --- @param self this writer
        drop: nosuspend function(takes self: ScalarWriter): nil

        --- Closes this writer and its destination, reporting whether it succeeded.
        --- @param self this writer
        --- @return whether the close succeeded
        --- @return a failure reason, when unsuccessful
        close: function(takes self: ScalarWriter): (boolean, string?)
    end

    --- Filesystem metadata and directory contents.
    ---
    --- Every operation here answers before a transfer could have started: it reads a
    --- name, a listing, or an attribute. Reading and writing a file's bytes is a
    --- separate layer.
    record Files
        --- What a resolved path refers to. A `symlink` answer only ever comes from
        --- `isSymlink`, since every other operation follows the link first.
        type Kind = "file" | "directory" | "symlink" | "other"

        --- A well-known user folder. Resolved from the environment, so a desktop that
        --- records its folders elsewhere is not consulted.
        type UserFolder = "home" | "documents" | "downloads" | "desktop" | "pictures" | "music" | "videos"

        --- One resolved path's attributes.
        record Info
            --- What the path refers to, after following symbolic links.
            kind: Kind

            --- The byte length of a file's contents.
            size: integer

            --- Seconds since the Unix epoch, with a fractional part where the
            --- platform records one.
            modified: number

            --- Whether the platform refuses writes to this path.
            readOnly: boolean
        end

        --- How an open file may be used. The three update modes read and write:
        --- `r+` needs an existing file, `w+` truncates one, and `a+` appends.
        type Mode = "r" | "w" | "a" | "r+" | "w+" | "a+"

        --- What a seek offset is measured from.
        type Origin = "set" | "current" | "end"

        --- Answers each line in turn, and nil at the end of the file.
        type LineIterator = function(): string?

        --- An open file, and the obligation to close it.
        ---
        --- Readers and writers opened from it satisfy the same [`nupp.io.Reader` and
        --- `nupp.io.Writer`](../docs/modules/nupp/io.md) contracts a buffer's do, so
        --- code written against those works over a file without knowing one is there.
        record File
            --- Opens a forward-only reader at the file's current position.
            --- @param self this file
            --- @return the new reader
            newReader: nosuspend function(self: File): affine(nupp.io.Reader, __nuppDestroyReader)

            --- Opens a forward-only writer at the file's current position.
            --- @param self this file
            --- @return the new writer
            newWriter: nosuspend function(self: File): affine(nupp.io.Writer, __nuppDestroyWriter)

            --- Answers the file's byte length without moving the cursor.
            --- @param self this file
            --- @return the byte length, or nil on failure
            --- @return a failure reason, when unsuccessful
            size: nosuspend function(self: File): (integer?, string?)

            --- Moves the cursor and answers where it landed.
            --- @param self this file
            --- @param offset the distance to move
            --- @param origin what the offset is measured from, defaulting to the
            ---     start
            --- @return the new position, or nil on failure
            --- @return a failure reason, when unsuccessful
            seek: nosuspend function(self: File, offset: integer?, origin: Origin?): (integer?, string?)

            --- Answers the cursor's current position.
            --- @param self this file
            --- @return the position, or nil on failure
            --- @return a failure reason, when unsuccessful
            position: nosuspend function(self: File): (integer?, string?)

            --- Pushes buffered writes at the operating system.
            --- @param self this file
            --- @return whether the flush succeeded
            --- @return a failure reason, when unsuccessful
            flush: nosuspend function(self: File): (boolean, string?)

            --- Whether this file has been closed.
            --- @param self this file
            --- @return whether it is closed
            isReleased: nosuspend function(self: File): boolean

            --- Closes the file as an ownership terminal. Repeated calls are safe.
            --- @param self this file
            drop: nosuspend function(takes self: File): nil

            --- Closes the file and reports whether it succeeded.
            --- @param self this file
            --- @return whether the close succeeded
            close: nosuspend function(takes self: File): boolean
        end

        --- A created temporary path, and the obligation to settle it.
        ---
        --- Closing removes it. `persist` moves it somewhere permanent instead and
        --- discharges the obligation, which is the whole reason to make one: write
        --- to a name nobody else can take, then put it where it belongs.
        record TemporaryPath
            --- Answers the created path.
            --- @param self this temporary path
            --- @return the path text
            toString: nosuspend function(self: TemporaryPath): string

            --- Moves this path to a permanent destination, replacing what is there.
            --- @param self this temporary path
            --- @param destination where to move it
            --- @return whether the move happened
            --- @return a failure reason, when unsuccessful
            persist: nosuspend function(self: TemporaryPath, destination: string | nupp.io.Path): (boolean, string?)

            --- Whether this path has been removed or persisted.
            --- @param self this temporary path
            --- @return whether it is settled
            isReleased: nosuspend function(self: TemporaryPath): boolean

            --- Removes the path as an ownership terminal. Repeated calls, and a call
            --- after `persist`, are safe and do nothing.
            --- @param self this temporary path
            drop: nosuspend function(takes self: TemporaryPath): nil

            --- Removes the path and reports whether it succeeded.
            --- @param self this temporary path
            --- @return whether the removal succeeded
            close: nosuspend function(takes self: TemporaryPath): boolean
        end

        --- One directory child, as the directory itself describes it.
        record Entry
            --- The child's name, without any directory part.
            name: string

            --- What the entry itself is, without following a symbolic link.
            kind: Kind
        end

        --- The generated part of a temporary name.
        record TemporaryOptions
            --- Where to create it, or the platform's temporary directory when
            --- omitted.
            directory: (string | nupp.io.Path)?

            --- Text before the generated part.
            prefix: string?

            --- Text after the generated part, such as an extension.
            suffix: string?
        end

        --- Filesystem metadata, directory contents, and the operations that move
        --- names rather than bytes.
        --- @internal
        record Library
            --- Describes one path, following symbolic links.
            ---
            --- #### Examples
            ---
            --- Read a file's size:
            ---
            --- ```nupp
            --- local info = assert(nupp.io.files.info("nupp.lua"))
            --- assert(info.kind == "file" and info.size > 0)
            --- ```
            --- @param path the path to describe
            --- @return the attributes, or nil when the path cannot be read
            --- @return a failure reason, when unsuccessful
            info: nosuspend function(path: string | nupp.io.Path): (Info?, string?)

            --- Whether a path resolves to anything at all.
            --- @param path the path to test
            --- @return whether it resolves
            exists: nosuspend function(path: string | nupp.io.Path): boolean

            --- Whether a path resolves to a regular file.
            --- @param path the path to test
            --- @return whether it is a file
            isFile: nosuspend function(path: string | nupp.io.Path): boolean

            --- Whether a path resolves to a directory.
            --- @param path the path to test
            --- @return whether it is a directory
            isDirectory: nosuspend function(path: string | nupp.io.Path): boolean

            --- Whether a path is itself a symbolic link, without following it.
            --- @param path the path to test
            --- @return whether it is a symbolic link
            isSymlink: nosuspend function(path: string | nupp.io.Path): boolean

            --- Reads a symbolic link's target without resolving it.
            --- @param path the link to read
            --- @return the target text, or nil on failure
            --- @return a failure reason, when unsuccessful
            readLink: nosuspend function(path: string | nupp.io.Path): (string?, string?)

            --- Creates a symbolic link.
            ---
            --- `kind` selects Windows's directory link and is ignored elsewhere,
            --- because only Windows distinguishes the two.
            --- @param target what the link points at
            --- @param link where to create the link
            --- @param kind the link kind, defaulting to a file link
            --- @return whether the link was created
            --- @return a failure reason, when unsuccessful
            createSymlink: nosuspend function(
                target: string | nupp.io.Path,
                link: string | nupp.io.Path,
                kind: ("file" | "directory")?
            ): (boolean, string?)

            --- Sets or clears a path's read-only attribute.
            --- @param path the path to change
            --- @param readOnly whether to refuse writes
            --- @return whether the attribute was set
            --- @return a failure reason, when unsuccessful
            setReadOnly: nosuspend function(path: string | nupp.io.Path, readOnly: boolean): (boolean, string?)

            --- Creates a directory and every missing parent. An existing directory
            --- succeeds.
            --- @param path the directory to create
            --- @return whether the directory exists afterwards
            --- @return a failure reason, when unsuccessful
            createDirectory: nosuspend function(path: string | nupp.io.Path): (boolean, string?)

            --- Removes a file, a symbolic link, or a directory.
            --- @param path the path to remove
            --- @param recursive whether to remove a directory's contents with it
            --- @return whether the path was removed
            --- @return a failure reason, when unsuccessful
            remove: nosuspend function(path: string | nupp.io.Path, recursive: boolean?): (boolean, string?)

            --- Renames a path, replacing an existing destination.
            --- @param from the path to rename
            --- @param to the new path
            --- @return whether the rename happened
            --- @return a failure reason, when unsuccessful
            rename: nosuspend function(from: string | nupp.io.Path, to: string | nupp.io.Path): (boolean, string?)

            --- Lists a directory's immediate children.
            ---
            --- #### Examples
            ---
            --- Count the modules beside a file:
            ---
            --- ```nupp
            --- local entries = assert(nupp.io.files.list("src"))
            --- for _, entry in ipairs(entries) do
            ---     print(entry.kind, entry.name)
            --- end
            --- ```
            --- @param path the directory to list
            --- @return the children in the platform's order, or nil on failure
            --- @return a failure reason, when unsuccessful
            list: nosuspend function(path: string | nupp.io.Path): ({Entry}?, string?)

            --- Expands a filesystem pattern into matching paths.
            ---
            --- `*` and `?` match within one path component, character classes use
            --- `[abc]` or `[!abc]`, and `**` crosses directory boundaries. The
            --- returned paths are sorted, and no matches is an empty list.
            --- @param pattern the filesystem pattern to expand
            --- @return the matching paths, or nil when the pattern or walk fails
            --- @return a failure reason, when unsuccessful
            glob: nosuspend function(pattern: string | nupp.io.Path): ({string}?, string?)

            --- Reads a whole file.
            ---
            --- #### Examples
            ---
            --- Read a file's bytes, or report why not:
            ---
            --- ```nupp
            --- local text, reason = nupp.io.files.read("nupp.lua")
            --- assert(text, reason)
            --- ```
            --- @param path the file to read
            --- @return the contents, or nil on failure
            --- @return a failure reason, when unsuccessful
            read: function(path: string | nupp.io.Path): (string?, string?)

            --- Writes a whole file, replacing its contents.
            --- @param path the file to write
            --- @param bytes the contents
            --- @return whether the write succeeded
            --- @return a failure reason, when unsuccessful
            write: function(path: string | nupp.io.Path, bytes: string | nupp.io.ByteView): (boolean, string?)

            --- Adds to the end of a file, creating it when it does not exist.
            --- @param path the file to extend
            --- @param bytes what to add
            --- @return whether the write succeeded
            --- @return a failure reason, when unsuccessful
            append: function(path: string | nupp.io.Path, bytes: string | nupp.io.ByteView): (boolean, string?)

            --- Writes a whole file through a temporary beside it, so an interrupted
            --- write leaves the destination as it was rather than half replaced.
            --- @param path the file to write
            --- @param bytes the contents
            --- @return whether the write succeeded
            --- @return a failure reason, when unsuccessful
            writeAtomic: function(path: string | nupp.io.Path, bytes: string | nupp.io.ByteView): (boolean, string?)

            --- Copies a file's contents over a destination.
            --- @param from the file to copy
            --- @param to where to copy it
            --- @return whether the copy succeeded
            --- @return a failure reason, when unsuccessful
            copy: function(from: string | nupp.io.Path, to: string | nupp.io.Path): (boolean, string?)

            --- Opens a file and hands over the obligation to close it.
            ---
            --- #### Examples
            ---
            --- Read a header without holding the whole file:
            ---
            --- ```nupp
            --- do
            ---     local file = assert(nupp.io.files.open("image.png"))
            ---     print(file:newReader():read(8))
            --- end
            --- ```
            --- @param path the file to open
            --- @param mode how it may be used, defaulting to reading
            --- @return the open file, or nil on failure
            --- @return a failure reason, when unsuccessful
            open: function(path: string | nupp.io.Path, mode: Mode?): (affine(File?, __nuppDestroyFile), string?)

            --- Iterates a file's lines, closing it at the end.
            ---
            --- A trailing carriage return is removed, so a file written on either
            --- platform reads the same. The iterator stops at the end of the file;
            --- abandoning it early leaves the file open until it is collected.
            --- @param path the file to read
            --- @return an iterator answering each line, or nil on failure
            --- @return a failure reason, when unsuccessful
            lines: function(path: string | nupp.io.Path): (LineIterator?, string?)

            --- Creates a uniquely named empty file and hands over the obligation to
            --- remove or persist it.
            ---
            --- The file is created rather than merely proposed, so no second caller
            --- can take the name in between.
            --- @param options where to create it and how to name it
            --- @return the created path, or nil on failure
            --- @return a failure reason, when unsuccessful
            createTemporaryFile: nosuspend function(
                options: TemporaryOptions?
            ): (affine(TemporaryPath?, __nuppDestroyTemporaryPath), string?)

            --- Creates a uniquely named empty directory and hands over the
            --- obligation to remove or persist it.
            --- @param options where to create it and how to name it
            --- @return the created path, or nil on failure
            --- @return a failure reason, when unsuccessful
            createTemporaryDirectory: nosuspend function(
                options: TemporaryOptions?
            ): (affine(TemporaryPath?, __nuppDestroyTemporaryPath), string?)

            --- Reads the process's current working directory.
            --- @return the current directory, or nil on failure
            --- @return a failure reason, when unsuccessful
            currentDirectory: nosuspend function(): (string?, string?)

            --- How many whole-file transfers this program is still holding.
            ---
            --- Whole-file reads, writes and copies settle on worker threads, and
            --- the lane that runs them is bounded. This answers what it holds,
            --- which is what a program that submitted more than it consumed needs
            --- to see.
            --- @return the number of live transfers
            pendingTransfers: nosuspend function(): integer

            --- Answers a well-known user folder.
            --- @param which the folder to locate
            --- @return the folder, or nil when the platform has no such folder
            --- @return a failure reason, when unsuccessful
            userFolder: nosuspend function(which: UserFolder): (string?, string?)
        end
    end

    --- An immutable platform-native UTF-8 filesystem path.
    record Path
        --- Creates a path by joining one or more components.
        ---
        --- #### Examples
        ---
        --- Build a path from components:
        ---
        --- ```nupp
        --- local source = nupp.io.Path.new("src", "main.nupp")
        --- assert(source:toString() == "src" .. nupp.io.Path.separator() .. "main.nupp")
        --- ```
        ---
        --- Normalize the path after joining its components:
        ---
        --- ```nupp
        --- local source = nupp.io.Path.new("src", "app", "..", "main.nupp"):normalize()
        --- assert(source:fileName() == "main.nupp")
        --- ```
        --- @param first the first path component
        --- @param ... the remaining path components
        --- @return the new path
        new: function(first: string, ...: string): Path

        --- Reads the process's current working directory.
        --- @return the current directory, or nil on failure
        --- @return a failure reason, when unsuccessful
        currentDirectory: function(): (Path?, string?)

        --- Returns the current platform's primary path separator.
        --- @return the path separator
        separator: function(): string

        --- Returns the native UTF-8 path text.
        --- @param self this path
        --- @return the path text
        toString: function(self: Path): string

        --- Appends path components using the current platform's rules.
        --- @param self this path
        --- @param ... the components to append
        --- @return the joined path
        join: function(self: Path, ...: string | Path): Path

        --- Removes lexical `.` and `..` components without accessing the filesystem.
        --- @param self this path
        --- @return the normalized path
        normalize: function(self: Path): Path

        --- Resolves a relative path against the current working directory.
        --- @param self this path
        --- @return the absolute path, or nil on failure
        --- @return a failure reason, when unsuccessful
        absolute: function(self: Path): (Path?, string?)

        --- Makes this path absolute, appends components, and normalizes the result.
        --- @param self this path
        --- @param ... the components to append
        --- @return the resolved path, or nil on failure
        --- @return a failure reason, when unsuccessful
        resolve: function(self: Path, ...: string | Path): (Path?, string?)

        --- Resolves filesystem links and returns the real path.
        --- @param self this path
        --- @return the canonical path, or nil on failure
        --- @return a failure reason, when unsuccessful
        canonicalize: function(self: Path): (Path?, string?)

        --- Computes this path relative to a compatible base path.
        --- @param self this path
        --- @param base the path to make this value relative to
        --- @return the relative path, or nil on failure
        --- @return a failure reason, when unsuccessful
        relativeTo: function(self: Path, base: string | Path): (Path?, string?)

        --- Returns the parent path, when one exists.
        --- @param self this path
        --- @return the parent path
        parent: function(self: Path): Path?

        --- Returns the final path component, when one exists.
        --- @param self this path
        --- @return the file name
        fileName: function(self: Path): string?

        --- Returns the file name without its final extension, when one exists.
        --- @param self this path
        --- @return the file stem
        stem: function(self: Path): string?

        --- Returns the final file-name extension without its separator.
        --- @param self this path
        --- @return the extension
        extension: function(self: Path): string?

        --- Replaces the final path component.
        --- @param self this path
        --- @param name the replacement file name, without path separators
        --- @return the modified path
        withFileName: function(self: Path, name: string): Path

        --- Replaces the final file-name extension.
        --- @param self this path
        --- @param extension the replacement extension, without path separators
        --- @return the modified path
        withExtension: function(self: Path, extension: string): Path

        --- Reports whether this path is absolute.
        --- @param self this path
        --- @return whether the path is absolute
        isAbsolute: function(self: Path): boolean

        --- Reports whether this path is relative.
        --- @param self this path
        --- @return whether the path is relative
        isRelative: function(self: Path): boolean
    end

    --- An immutable normalized absolute URI.
    record URI
        --- Parses and normalizes an absolute URI.
        --- @param value URI text or its individual components
        --- @return the parsed URI, or nil on failure
        --- @return a failure reason, when unsuccessful
        new: function(value: string | URI.Components): (URI?, string?)

        --- Checks whether text is a valid absolute URI without retaining an object.
        --- @param text the URI text to validate
        --- @return whether the text is valid
        --- @return a failure reason, when invalid
        validate: function(text: string): (boolean, string?)

        --- Reports whether a value is a URI object.
        --- @param value the value to inspect
        --- @return whether the value is a URI
        isURI: function(value: any): boolean

        --- Components accepted when constructing an absolute URI.
        record Components
            --- The required URI scheme.
            scheme: string

            --- Optional user information, including a password when needed.
            userInfo: string?

            --- The optional host name or address.
            host: string?

            --- The optional port from 0 through 65535.
            port: integer?

            --- The path, or an empty path when omitted.
            path: string?

            --- The optional query without its leading `?`.
            query: string?

            --- The optional fragment without its leading `#`.
            fragment: string?
        end

        --- Returns the complete normalized URI text.
        --- @param self this URI
        --- @return the URI text
        toString: function(self: URI): string

        --- Returns the normalized URI scheme.
        --- @param self this URI
        --- @return the scheme
        scheme: function(self: URI): string

        --- Returns the complete authority component, when present.
        --- @param self this URI
        --- @return the authority
        authority: function(self: URI): string?

        --- Returns the username component, or an empty string when absent.
        --- @param self this URI
        --- @return the username
        username: function(self: URI): string

        --- Returns the password component, when present.
        --- @param self this URI
        --- @return the password
        password: function(self: URI): string?

        --- Returns the normalized host, when present.
        --- @param self this URI
        --- @return the host
        host: function(self: URI): string?

        --- Returns the port, when explicitly present.
        --- @param self this URI
        --- @return the port
        port: function(self: URI): integer?

        --- Returns the URI path component.
        --- @param self this URI
        --- @return the path
        path: function(self: URI): string

        --- Returns the query without its leading `?`, when present.
        --- @param self this URI
        --- @return the query
        query: function(self: URI): string?

        --- Returns the fragment without its leading `#`, when present.
        --- @param self this URI
        --- @return the fragment
        fragment: function(self: URI): string?

        --- Returns the complete user-information component, when present.
        --- @param self this URI
        --- @return the user information
        userInfo: function(self: URI): string?

        --- Returns a copy with a replacement scheme.
        --- @param self this URI
        --- @param scheme the replacement scheme
        --- @return the modified URI
        withScheme: function(self: URI, scheme: string): URI

        --- Returns a copy with replacement or removed user information.
        --- @param self this URI
        --- @param userInfo the replacement, or nil to remove it
        --- @return the modified URI
        withUserInfo: function(self: URI, userInfo: string?): URI

        --- Returns a copy with a replacement or removed host.
        --- @param self this URI
        --- @param host the replacement, or nil to remove it
        --- @return the modified URI
        withHost: function(self: URI, host: string?): URI

        --- Returns a copy with a replacement or removed port.
        --- @param self this URI
        --- @param port the replacement from 0 through 65535, or nil to remove it
        --- @return the modified URI
        withPort: function(self: URI, port: integer?): URI

        --- Returns a copy with a replacement path.
        --- @param self this URI
        --- @param path the replacement path
        --- @return the modified URI
        withPath: function(self: URI, path: string): URI

        --- Returns a copy with a replacement or removed query.
        --- @param self this URI
        --- @param query the replacement without `?`, or nil to remove it
        --- @return the modified URI
        withQuery: function(self: URI, query: string?): URI

        --- Returns a copy with a replacement or removed fragment.
        --- @param self this URI
        --- @param fragment the replacement without `#`, or nil to remove it
        --- @return the modified URI
        withFragment: function(self: URI, fragment: string?): URI

        --- Appends path text without interpreting it as a URI reference.
        --- @param self this URI
        --- @param path the path text to append
        --- @return the modified URI
        concatPath: function(self: URI, path: string): URI

        --- Replaces the scheme and authority while retaining resource components.
        --- @param self this URI
        --- @param endpoint the URI supplying the scheme and authority
        --- @return the endpoint-rerouted URI
        withEndpoint: function(self: URI, endpoint: URI): URI

        --- Resolves a URI reference according to RFC reference-resolution rules.
        --- @param self this URI
        --- @param reference the URI reference to resolve
        --- @return the resolved URI, or nil on failure
        --- @return a failure reason, when unsuccessful
        resolve: function(self: URI, reference: string): (URI?, string?)
    end

    --- Creates an owned growable byte buffer.
    --- @param initial initial bytes, an initial capacity, or nothing for an empty
    ---     buffer
    --- @return the new buffer
    newBuffer: function(initial: integer | string?): affine(Buffer, __nuppDestroyBuffer)

    --- Creates a forward-only reader over a string.
    --- @param text the bytes to read
    --- @return the new reader
    newStringReader: function(text: string): affine(Reader, __nuppDestroyReader)

    --- Creates a forward-only reader that consumes a byte queue, which is how a
    --- LuaJIT `string.buffer` joins this layer without a copy of everything in it.
    --- Reading drains the queue, so the queue's own `get` may be interleaved.
    --- @param source the queue to consume
    --- @return the new reader
    newQueueReader: function(source: ByteQueue): Reader

    --- Creates a cursor for sized integer and float reads.
    ---
    --- A string, snapshot or buffer is read from a copy of its bytes taken here, and
    --- reports its `remaining` count. A reader or a queue is consumed in place: the
    --- reader answers no count, the queue answers what it still holds.
    ---
    --- @param source the bytes, snapshot, buffer, reader or queue to read
    --- @return the new reader
    newScalarReader: function(source: string | ByteQueue): affine(ScalarReader, __nuppDestroyScalarReader)
        & function(borrows source: ByteView | Buffer): affine(ScalarReader, __nuppDestroyScalarReader)
        & function(takes source: Reader): affine(ScalarReader, __nuppDestroyScalarReader)

    --- Creates a cursor for sized integer and float writes.
    ---
    --- A buffer is appended to, keeping what it already holds. A writer receives the
    --- bytes as they are written. Omitting the destination starts a fresh buffer,
    --- which `ScalarWriter:buffer` hands back.
    ---
    --- @param destination the buffer or writer to append to, or nothing for a fresh
    ---     buffer
    --- @return the new writer
    newScalarWriter: function(): affine(ScalarWriter, __nuppDestroyScalarWriter)
        & function(borrows destination: Buffer): affine(ScalarWriter, __nuppDestroyScalarWriter) borrows (destination)
        & function(takes destination: Writer): affine(ScalarWriter, __nuppDestroyScalarWriter)

    --- Filesystem metadata, directory contents, and the operations that move
    --- names rather than bytes.
    --- @namespace
    files: Files.Library
end

--- Two-dimensional vector operations on number pairs.
--- @internal
record nupp.Vec2Library
    --- Adds two vectors.
    --- @param ax the first vector's x component
    --- @param ay the first vector's y component
    --- @param bx the second vector's x component
    --- @param by the second vector's y component
    --- @return the sum's x component
    --- @return the sum's y component
    add: function(ax: number, ay: number, bx: number, by: number): (number, number)

    --- Subtracts the second vector from the first.
    --- @param ax the first vector's x component
    --- @param ay the first vector's y component
    --- @param bx the second vector's x component
    --- @param by the second vector's y component
    --- @return the difference's x component
    --- @return the difference's y component
    subtract: function(ax: number, ay: number, bx: number, by: number): (number, number)

    --- Multiplies a vector by a scalar.
    --- @param x the vector's x component
    --- @param y the vector's y component
    --- @param factor the scale factor
    --- @return the scaled x component
    --- @return the scaled y component
    scale: function(x: number, y: number, factor: number): (number, number)

    --- Computes the dot product of two vectors.
    --- @param ax the first vector's x component
    --- @param ay the first vector's y component
    --- @param bx the second vector's x component
    --- @param by the second vector's y component
    --- @return the dot product
    dot: function(ax: number, ay: number, bx: number, by: number): number

    --- Computes the signed scalar cross product of two vectors.
    --- @param ax the first vector's x component
    --- @param ay the first vector's y component
    --- @param bx the second vector's x component
    --- @param by the second vector's y component
    --- @return the scalar cross product
    cross: function(ax: number, ay: number, bx: number, by: number): number

    --- Computes a vector's squared magnitude without a square root.
    --- @param x the vector's x component
    --- @param y the vector's y component
    --- @return the squared magnitude
    lengthSquared: function(x: number, y: number): number

    --- Computes a vector's magnitude.
    --- @param x the vector's x component
    --- @param y the vector's y component
    --- @return the magnitude
    length: function(x: number, y: number): number

    --- Computes the squared distance between two points without a square root.
    --- @param ax the first point's x coordinate
    --- @param ay the first point's y coordinate
    --- @param bx the second point's x coordinate
    --- @param by the second point's y coordinate
    --- @return the squared distance
    distanceSquared: function(ax: number, ay: number, bx: number, by: number): number

    --- Computes the distance between two points.
    --- @param ax the first point's x coordinate
    --- @param ay the first point's y coordinate
    --- @param bx the second point's x coordinate
    --- @param by the second point's y coordinate
    --- @return the distance
    distance: function(ax: number, ay: number, bx: number, by: number): number

    --- Returns a unit vector in the same direction, or `(0, 0)` for zero.
    --- @param x the vector's x component
    --- @param y the vector's y component
    --- @return the normalized x component
    --- @return the normalized y component
    normalize: function(x: number, y: number): (number, number)

    --- Linearly interpolates or extrapolates between two vectors.
    --- @param ax the starting x component
    --- @param ay the starting y component
    --- @param bx the ending x component
    --- @param by the ending y component
    --- @param t the unclamped interpolation factor
    --- @return the interpolated x component
    --- @return the interpolated y component
    lerp: function(ax: number, ay: number, bx: number, by: number, t: number): (number, number)

    --- Moves toward a target by at most a distance, without overshooting.
    --- @param ax the starting x component
    --- @param ay the starting y component
    --- @param bx the target x component
    --- @param by the target y component
    --- @param distance the maximum step; nonpositive values leave the start unchanged
    --- @return the resulting x component
    --- @return the resulting y component
    moveTowards: function(ax: number, ay: number, bx: number, by: number, distance: number): (number, number)

    --- Rotates a vector around the origin.
    --- @param x the vector's x component
    --- @param y the vector's y component
    --- @param radians the signed rotation in radians
    --- @return the rotated x component
    --- @return the rotated y component
    rotate: function(x: number, y: number, radians: number): (number, number)

    --- Computes a vector's signed direction from the positive x-axis.
    --- @param x the vector's x component
    --- @param y the vector's y component
    --- @return the angle in radians, or zero for the zero vector
    angle: function(x: number, y: number): number

    --- Computes the smallest unsigned angle between two vectors.
    --- @param ax the first vector's x component
    --- @param ay the first vector's y component
    --- @param bx the second vector's x component
    --- @param by the second vector's y component
    --- @return the angle from zero through pi, or zero for a zero vector
    angleBetween: function(ax: number, ay: number, bx: number, by: number): number

    --- Computes the smallest signed angle from the first vector to the second.
    --- @param ax the first vector's x component
    --- @param ay the first vector's y component
    --- @param bx the second vector's x component
    --- @param by the second vector's y component
    --- @return the angle in `[-pi, pi)`, or zero for a zero vector
    signedAngleBetween: function(ax: number, ay: number, bx: number, by: number): number

    --- Projects a vector onto another vector.
    --- @param x the vector's x component
    --- @param y the vector's y component
    --- @param ontoX the projection axis's x component
    --- @param ontoY the projection axis's y component
    --- @return the projected x component, or zero for a zero axis
    --- @return the projected y component, or zero for a zero axis
    project: function(x: number, y: number, ontoX: number, ontoY: number): (number, number)

    --- Reflects a vector across a normal.
    --- @param x the vector's x component
    --- @param y the vector's y component
    --- @param normalX the normal's x component
    --- @param normalY the normal's y component
    --- @return the reflected x component, or the input x for a zero normal
    --- @return the reflected y component, or the input y for a zero normal
    reflect: function(x: number, y: number, normalX: number, normalY: number): (number, number)
end

--- Scalar angle helpers and two-dimensional vector operations.
