["/decls/prelude_impl.d.nupp"] = [[
-- Ordinary implementation bodies for declarations in prelude.d.nupp. This unit is
-- checked and generated under the declaration prelude's logical origin, so const
-- function identities and their runtime registry publications are the same identities
-- the public declarations sealed into generic defaults.

local function __nuppDestroyByteView(takes value: nupp.io.ByteView): nil
    nosuspend do
        value:drop()
    end
end

local function __nuppDestroyReader(takes value: nupp.io.Reader): nil
    nosuspend do
        value:drop()
    end
end

local function __nuppDestroyWriter(takes value: nupp.io.Writer): nil
    nosuspend do
        value:drop()
    end
end

local function __nuppDestroyBuffer(takes value: nupp.io.Buffer): nil
    nosuspend do
        value:drop()
    end
end

local function __nuppDestroyFile(takes value: nupp.io.Files.File): nil
    nosuspend do
        value:drop()
    end
end

local function __nuppDestroyTemporaryPath(takes value: nupp.io.Files.TemporaryPath): nil
    nosuspend do
        value:drop()
    end
end

local function __nuppDestroyScalarReader(takes value: nupp.io.ScalarReader): nil
    nosuspend do
        value:drop()
    end
end

local function __nuppDestroyScalarWriter(takes value: nupp.io.ScalarWriter): nil
    nosuspend do
        value:drop()
    end
end

-- Referencing each implementation as an affine terminal publishes its runtime
-- provider under the declaration identity sealed into prelude.d.nupp.
local type __NuppByteViewCleanup = affine(nupp.io.ByteView, __nuppDestroyByteView)
local type __NuppReaderCleanup = affine(nupp.io.Reader, __nuppDestroyReader)
local type __NuppWriterCleanup = affine(nupp.io.Writer, __nuppDestroyWriter)
local type __NuppBufferCleanup = affine(nupp.io.Buffer, __nuppDestroyBuffer)
local type __NuppFileCleanup = affine(nupp.io.Files.File, __nuppDestroyFile)
local type __NuppTemporaryPathCleanup = affine(nupp.io.Files.TemporaryPath, __nuppDestroyTemporaryPath)
local type __NuppScalarReaderCleanup = affine(nupp.io.ScalarReader, __nuppDestroyScalarReader)
local type __NuppScalarWriterCleanup = affine(nupp.io.ScalarWriter, __nuppDestroyScalarWriter)
]],
["/decls/re.d.nupp"] = [[
-- Typed declaration for the textual LPeg grammar module bundled by Nupp.

local record re
    --- Compiles an LPeg `re` expression, or returns an existing pattern unchanged.
    compile: function(pattern: any, definitions: table?): any

    --- Compiles `pattern` if needed and matches it against `subject`.
    match: function(subject: string, pattern: any, init: integer?): any

    --- Finds the first match and returns its inclusive byte range.
    find: function(subject: string, pattern: any, init: integer?): (integer?, integer?)

    --- Replaces every match with a literal, lookup table, or callback result.
    gsub: function(subject: string, pattern: any, replacement: string | table | function(...: any): any): string

    --- Rebuilds the predefined locale-dependent character classes.
    updatelocale: function(): nil
end

return re
]],
["/decls/stringbuffer.d.nupp"] = [=[
--[[
Declarations for LuaJIT's string.buffer module, loaded for
`require("string.buffer")`.

A buffer is a FIFO: the `put*` and `encode` methods append to the end, and the
`get*` and `decode` methods consume from the front. Methods chain;
`putcdata`, `ref`, and `reserve` sit at the FFI boundary.

Length with `#buf`, concatenation with `..`, and `tostring` are metamethods, so
they are not members of the record below; use `buf:tostring()`.
]]

--- A mutable, binary-transparent byte sequence. Methods with nothing else to return
--- hand back the buffer itself, so calls chain.
---
--- Exported, so code that passes buffers around can name the type: `function
--- render(out: string.buffer.Buffer): string.buffer.Buffer`.
record Buffer
    metamethod __len: function(self): integer
    metamethod __concat: function(self, other: any): string
    metamethod __tostring: function(self): string

    --- Appends each argument: a string, a number, another buffer, or any object with a
    --- `__tostring` metamethod.
    ---
    --- @param b the buffer to append to
    --- @param ... the values to append, in order
    --- @return `b`
    put: function(exclusive b: Buffer, ...: any): Buffer borrows (b)

    --- Appends the arguments formatted by `fmt`, which takes the same directives as
    --- `string.format`.
    ---
    --- @param b the buffer to append to
    --- @param fmt the format string
    --- @param ... the values that the directives consume
    --- @return `b`
    putf: function(exclusive b: Buffer, fmt: string, ...: any): Buffer borrows (b)

    --- Appends `len` bytes read from the memory that `data` points to. The cdata object
    --- has to be convertible to a pointer.
    ---
    --- @param b the buffer to append to
    --- @param data the memory to copy from
    --- @param len how many bytes to copy
    --- @return `b`
    putcdata: function(exclusive b: Buffer, data: voidptr, len: uint64): Buffer borrows (b)

    --- Replaces the buffer contents with a reference to `data`, freeing any space
    --- already allocated. Nothing is copied until the buffer is written to again, and
    --- the reference keeps `data` alive meanwhile.
    ---
    --- @param b the buffer to reset onto `data`
    --- @param data the string, or cdata pointer, to reference
    --- @param len how many bytes `data` holds, required for cdata
    --- @return `b`
    set: function(exclusive b: Buffer, data: any, len: uint64?): Buffer borrows (b)

    --- Consumes bytes from the front of the buffer and returns them. With no argument
    --- the whole buffer is consumed; each further argument takes one more string, and a
    --- nil argument takes whatever remains.
    ---
    --- @param b the buffer to read from
    --- @param ... how many bytes each returned string takes
    --- @return one string per argument, or the whole buffer when given none
    get: function(exclusive b: Buffer, ...: integer?): string

    --- Returns the buffer contents as a string, without consuming them.
    ---
    --- @param b the buffer to read
    --- @return the buffer contents
    tostring: function(b: Buffer): string

    --- Empties the buffer, keeping the space it has already allocated so it can be
    --- refilled without reallocating.
    ---
    --- @param b the buffer to empty
    --- @return `b`
    reset: function(exclusive b: Buffer): Buffer borrows (b)

    --- Frees the buffer space at once, leaving the object itself intact and empty. The
    --- collector does this on its own, so it is only worth calling when the memory has
    --- to go back immediately.
    ---
    --- @param b the buffer to free
    --- @return `b`
    free: function(exclusive b: Buffer): Buffer borrows (b)

    --- Consumes `n` bytes from the front of the buffer and discards them, stopping at
    --- the end of the data.
    ---
    --- @param b the buffer to skip in
    --- @param n how many bytes to discard
    --- @return `b`
    skip: function(exclusive b: Buffer, n: integer): Buffer borrows (b)

    --- Returns a pointer to the buffer data, for zero-copy reads and in-place writes.
    --- The data is not zero-terminated, so the length has to travel with the pointer.
    ---
    --- @param b the buffer to point into
    --- @return the unconsumed data, as the zero-based `uint8_t *` view that
    ---     bytewise reads and writes go through
    --- @return how many bytes are readable there
    ref: function(borrows b: Buffer): (uint8[?] borrows (b), uint64)

    --- Reserves at least `size` bytes of write space and returns a pointer to it. The
    --- space is uninitialized, and joins the buffer data only once `commit` says how
    --- much of it was written.
    ---
    --- @param b the buffer to reserve space in
    --- @param size how many bytes are needed at least
    --- @return the write space, as the zero-based `uint8_t *` view that
    ---     bytewise writes go through
    --- @return how many bytes are actually available, at least `size`
    reserve: function(exclusive b: Buffer, size: integer): (uint8[?] borrows (b), uint64)

    --- Appends the first `used` bytes of the space handed out by the last `reserve` to
    --- the buffer data.
    ---
    --- @param b the buffer that space was reserved in
    --- @param used how many bytes were written
    --- @return `b`
    commit: function(exclusive b: Buffer, used: integer): Buffer borrows (b)

    --- Serializes `obj` and appends the encoding to the buffer. Encodings concatenate,
    --- so several objects can be streamed into one buffer.
    ---
    --- @param b the buffer to append to
    --- @param obj the value to serialize
    --- @return `b`
    encode: function(exclusive b: Buffer, obj: any): Buffer borrows (b)

    --- Deserializes one object from the front of the buffer, leaving any data after it
    --- in place. Raises on malformed or truncated input.
    ---
    --- @param b the buffer to read from
    --- @return the decoded value, of any supported type
    decode: function(exclusive b: Buffer): any
end

--- Creates a buffer. The options table may carry a `dict` array of string keys that
--- occur often and a `metatable` array of metatables, which the serializer encodes as
--- indexes; an encoder and its decoder must share them, and neither table may be
--- modified afterwards.
---
--- @param size a minimum initial buffer size, or the options table when it
---     is the only argument
--- @param options the serialization options
--- @return the new buffer
local new: function(size: (integer | table)?, options: table?): Buffer

--- Serializes `v` to a string. Raises on unsupported types, circular references, and
--- nesting too deep to encode.
---
--- @param v the value to serialize
--- @return the encoded bytes
local encode: function(v: any): string

--- Deserializes a whole encoded string. Raises on malformed input, and also when
--- anything is left over after one top-level object.
---
--- @param s the encoded bytes
--- @return the decoded value, of any supported type
local decode: function(s: string): any

return {new = new, encode = encode, decode = decode}
]=],
["/nupp/data/bitset.nupp"] = [=[
module nupp.data.bitset

--[[
Multi-word bitsets over GC-managed 32-bit words.

LuaJIT gives one 32-bit word at a time and no population count or trailing-zero
operation -- those are table lookups here, which is the floor Lua can reach --
so everything that makes a bitset a bitset lives here: the word loop,
range masks that span word boundaries, the used-word bound, and counting across
words. Storage is FFI cdata; the pointer is private, so no caller can hold one
across a growth that replaces it.

Bit indexes count from 0, because bit `i` lives in word `i / WORD_BITS` and
fighting that costs correctness. `count` is resolved on demand rather than
maintained through set algebra: union, intersection and difference are word
loops whose per-word popcount would otherwise cost more than the operation.

Reached as `nupp.data.bitset`, which the prelude declares and the stdlib
installer loads. That is the only public spelling a program has. This declared
implementation module is internal and uses an `impl` suffix because a module at
`nupp.data.bitset` would shadow the intrinsic member it implements.
]]

local bitset = {}
local ffi = require("ffi")

const band = bit.band
const bnot = bit.bnot
const bor = bit.bor
const bxor = bit.bxor
const lshift = bit.lshift
const rshift = bit.rshift
const tobit = bit.tobit

--- How many bits one stored word holds. Derive word arithmetic from this rather
--- than assuming a width.
--- @export
const bitset.WORD_BITS = 32

-- 5 and 31 are WORD_BITS as a shift and a mask. They are spelled as literals
-- because LuaJIT folds a literal shift and would not fold a table read.
const BITS_PER_WORD = 32
const WORD_SHIFT = 5
const BIT_MASK = 31
const ALL_ONES = -1
const DEFAULT_BITS = 64

const HALF_MASK = 0xFFFF
const HALF_SHIFT = 16

-- Half-word rather than byte tables: two probes per word instead of four. That
-- measured 1.58 times faster for the population count and 1.20 for the lowest
-- bit, against 128KB of static tables and the loop below that fills them. The
-- multiply-free SWAR population count was a wash, and the usual multiply form
-- cannot be spelled here because a Lua multiply goes through a double and loses
-- the low bits it depends on.
--
-- Nothing in Lua closes the rest of the gap: the machine has one instruction for
-- each of these and the bit library exposes neither.
local POPCOUNT_HALF = ffi.new("uint8_t[65536]") as uint8[?]
local CTZ_HALF = ffi.new("uint8_t[65536]") as uint8[?]

unsafe do
    -- Each half is built from the one below it: the population of a value is the
    -- population of the value without its lowest bit, plus one.
    POPCOUNT_HALF[0] = 0
    for value = 1, 65535 do
        POPCOUNT_HALF[value] = POPCOUNT_HALF[band(value, value - 1)] + 1
    end

    -- A half with nothing set has no trailing-zero answer; 16 makes a caller that
    -- probes the other half land on the right offset without a separate test.
    CTZ_HALF[0] = 16
    for value = 1, 65535 do
        CTZ_HALF[value] = band(value, 1) == 1 ? 0 : CTZ_HALF[rshift(value, 1)] + 1
    end
end

--- Set bits in one word.
local function popcount(word: integer): integer
    unsafe do
        return (
            POPCOUNT_HALF[band(word, HALF_MASK)] + POPCOUNT_HALF[band(rshift(word, HALF_SHIFT), HALF_MASK)]
        ) as integer
    end
end

--- The position of the lowest set bit of a non-zero word.
local function lowestBit(word: integer): integer
    unsafe do
        local half = band(word, HALF_MASK)
        if half ~= 0 then
            return CTZ_HALF[half]
        end

        return (HALF_SHIFT + CTZ_HALF[band(rshift(word, HALF_SHIFT), HALF_MASK)]) as integer
    end
end

--- The number of words needed to hold `bits` bits, at least one.
local function wordsFor(bits: integer): integer
    local words = rshift(bits + BIT_MASK, WORD_SHIFT)
    return words < 1 ? 1 : words
end

--- A growable set of bit positions counting from 0.
---
--- Reading, clearing and testing a position past the end are defined and cheap.
--- Setting one grows, which reallocates private storage; nothing observable
--- survives that, because the storage is never handed out.
--- @export
record bitset.Bitset
    --- Zero-based words, lowest bit first. Every word from `used` up to
    --- `capacity` is zero, which is the invariant every word loop relies on.
    private words: uint32[?]

    --- Words allocated.
    private capacity: integer

    --- An upper bound on the words that may hold a set bit: every word at or
    --- above it is zero. Deliberately not the exact high-water mark, because
    --- keeping that exact costs a backwards scan on every clear and every
    --- intersection.
    private used: integer

    --- The last resolved population, meaningful only when `stale` is false.
    private population: integer

    --- Whether `population` needs recomputing. Set algebra marks it rather than
    --- paying two popcounts per word to keep a number most callers never read.
    private stale: boolean

    --- Grows storage so at least `bits` bits fit. Only grows, and never returns
    --- storage. A growth at least doubles, so repeated small growths stay
    --- amortised.
    --- @param bits how many bits must fit
    function reserve(self, bits: integer): nil
        local needed = wordsFor(bits)
        if needed <= self.capacity then
            return
        end

        local doubled = self.capacity * 2
        local grown = needed > doubled ? needed : doubled
        local fresh = ffi.new("uint32_t[?]", grown) as uint32[?]
        ffi.copy(fresh as any, self.words as any, self.capacity * 4)
        self.words = fresh
        self.capacity = grown
    end

    --- Adds a bit, growing when it is past the end.
    --- @param index the bit position, counting from 0
    --- @raises when index is negative
    function set(self, index: integer): nil
        -- `rshift` is unsigned, so a negative index names a word near 2^27 and
        -- the store below would land far outside the array. `get` and `clear`
        -- read such an index as past the end and answer with nothing; a write
        -- has no such reading, so it is refused here.
        if index < 0 then
            error("bitset index cannot be negative", 2)
        end

        local word = rshift(index, WORD_SHIFT)
        if word >= self.capacity then
            self:reserve(index + 1)
        end

        unsafe do
            local previous = tobit(self.words[word])
            local mask = lshift(1, band(index, BIT_MASK))
            if band(previous, mask) == 0 then
                self.words[word] = bor(previous, mask)
                if not self.stale then
                    self.population = self.population + 1
                end
                if word >= self.used then
                    self.used = word + 1
                end
            end
        end
    end

    --- Removes a bit. Never allocates, and never narrows the used-word bound,
    --- so it stays constant-time whichever bit it was.
    --- @param index the bit position, counting from 0. One past the end, a
    ---     negative one included, does nothing.
    function clear(self, index: integer): nil
        local word = rshift(index, WORD_SHIFT)
        if word >= self.used then
            return
        end

        unsafe do
            local previous = tobit(self.words[word])
            local mask = lshift(1, band(index, BIT_MASK))
            if band(previous, mask) ~= 0 then
                self.words[word] = band(previous, bnot(mask))
                if not self.stale then
                    self.population = self.population - 1
                end
            end
        end
    end

    --- Whether a bit is set.
    --- @param index the bit position, counting from 0
    --- @return false for any position past the end, so no bound check is needed
    ---     at the call site
    function get(self, index: integer): boolean
        local word = rshift(index, WORD_SHIFT)
        if word >= self.used then
            return false
        end

        unsafe do
            return band(tobit(self.words[word]), lshift(1, band(index, BIT_MASK))) ~= 0
        end
    end

    --- Adds every bit in the inclusive range, one word-mask write per word
    --- rather than one operation per bit.
    --- @param low the first position added, counting from 0
    --- @param high the last position added. Below `low` adds nothing, so an
    ---     empty range needs no guard at the call site.
    --- @raises when low is negative
    function setRange(self, low: integer, high: integer): nil
        if high < low then
            return
        end
        if low < 0 then
            error("bitset range cannot start below zero", 2)
        end

        self:reserve(high + 1)

        local firstWord = rshift(low, WORD_SHIFT)
        local lastWord = rshift(high, WORD_SHIFT)
        local lowBit = band(low, BIT_MASK)
        local highBit = band(high, BIT_MASK)
        local head = bnot(lshift(1, lowBit) - 1)
        local tail = highBit == BIT_MASK ? ALL_ONES : lshift(1, highBit + 1) - 1

        -- Whole words are written at a time, so the population moves by the
        -- difference across the touched words rather than by one per bit. That
        -- difference is taken in the same pass as the writes: a separate pass
        -- before and after measured twice as slow at every width.
        --
        -- Two things keep the count off the per-word path where it can be. A
        -- full middle word ends as all ones, so its new population is known and
        -- only the old one is read. A word at or above `used` is zero, so it
        -- needs no read at all.
        local exact = not self.stale
        local added = 0
        -- Hoisted after `reserve`, which is the only thing here that can replace
        -- the array. Every loop below is then one field read shorter per word.
        local words = self.words
        local used = self.used
        unsafe do
            if firstWord == lastWord then
                local old = tobit(words[firstWord])
                local new = bor(old, band(head, tail))
                words[firstWord] = new
                if exact then
                    added = popcount(new) - popcount(old)
                end
            else
                local old = tobit(words[firstWord])
                local new = bor(old, head)
                words[firstWord] = new
                if exact then
                    added = popcount(new) - popcount(old)
                end

                -- Middle words that already hold bits, and then the ones known
                -- to be zero, which are counted without being read.
                local lastMiddle = lastWord - 1
                local reached = used - 1 < lastMiddle ? used - 1 : lastMiddle
                local counted = reached < firstWord ? firstWord : reached
                if exact then
                    for word = firstWord + 1, counted do
                        added = added + BITS_PER_WORD - popcount(tobit(words[word]))
                        words[word] = ALL_ONES
                    end
                    if counted < lastMiddle then
                        added = added + BITS_PER_WORD * (lastMiddle - counted)
                    end
                    for word = counted + 1, lastMiddle do
                        words[word] = ALL_ONES
                    end
                else
                    for word = firstWord + 1, lastMiddle do
                        words[word] = ALL_ONES
                    end
                end

                old = tobit(words[lastWord])
                new = bor(old, tail)
                words[lastWord] = new
                if exact then
                    added = added + popcount(new) - popcount(old)
                end
            end

            if exact then
                self.population = (self.population + added) as integer
            end
        end

        if lastWord >= self.used then
            self.used = lastWord + 1
        end
    end

    --- How many bits are set. Resolves a pending recount, so a caller that
    --- reads it every frame pays for the set algebra it skipped; one that never
    --- reads it never pays.
    --- @return the number of set bits
    function count(self): integer
        if not self.stale then
            return self.population
        end

        -- Hoisted: nothing here grows, so the field read is loop-invariant and
        -- the loop should not repeat it per word.
        local words = self.words
        local total = 0
        unsafe do
            for word = 0, self.used - 1 do
                total = total + popcount(tobit(words[word]))
            end
        end
        local resolved = total as integer
        self.population = resolved
        self.stale = false

        return resolved
    end

    --- Whether nothing is set. Says nothing about capacity.
    --- @return true when no bit is set
    function isEmpty(self): boolean
        return self:count() == 0
    end

    --- Removes every bit, keeping capacity so a set reused each frame stops
    --- allocating once it has reached its peak.
    function clearAll(self): nil
        if self.used > 0 then
            ffi.fill(self.words as any, self.used * 4, 0)
            self.used = 0
        end
        self.population = 0
        self.stale = false
    end

    --- Removes every bit, then adds exactly one.
    --- @param index the one position left set, counting from 0
    --- @raises when index is negative
    function setOnly(self, index: integer): nil
        self:clearAll()
        self:set(index)
    end

    --- An upper bound on the words that may hold a set bit. Every word at or
    --- above it is zero, and it is not narrowed by `clear` or by intersection,
    --- so it may exceed the exact high-water mark.
    --- @return the number of words a word-at-a-time walk must visit
    function wordCount(self): integer
        return self.used
    end

    --- One stored word. Word `w` holds positions `w * WORD_BITS` through
    --- `w * WORD_BITS + WORD_BITS - 1`, lowest position first.
    --- @param index a word index counting from 0, bounded by `wordCount`
    --- @return the word as a signed value, so one with its top bit set reads
    ---     negative, and 0 for any index outside the bound
    function wordAt(self, index: integer): integer
        if index < 0 or index >= self.used then
            return 0
        end

        unsafe do
            return tobit(self.words[index])
        end
    end

    --- The lowest set position at or after `from`.
    ---
    --- Stateless, so nested walks do not interfere and a mutation between calls
    --- cannot invalidate a walk in progress.
    --- @param from the lowest position that may be returned, counting from 0
    --- @return that position, or -1 when there is none
    function nextSetBit(self, from: integer): integer
        local start = from < 0 ? 0 : from
        local first = rshift(start, WORD_SHIFT)
        local used = self.used
        if first >= used then
            return -1
        end

        local words = self.words
        -- A bounded `for` rather than an unbounded loop over the words. An
        -- unbounded one is an inner loop LuaJIT re-detects on every pass of
        -- whatever loop the walk sits in, and the thrash costs far more than the
        -- scan: the first shape of this measured nine times slower than the
        -- stateful scan it replaced.
        unsafe do
            local partial = tobit(words[first])
            local offset = band(start, BIT_MASK)
            if offset ~= 0 then
                partial = band(partial, bnot(lshift(1, offset) - 1))
            end
            if partial ~= 0 then
                return lshift(first, WORD_SHIFT) + lowestBit(partial)
            end

            for word = first + 1, used - 1 do
                local bits = tobit(words[word])
                if bits ~= 0 then
                    return lshift(word, WORD_SHIFT) + lowestBit(bits)
                end
            end
        end

        return -1
    end

    --- Writes every set position at or after `from` into `target`, lowest first.
    ---
    --- One call rather than one per position. A walk pays a call and a word read
    --- for every position it returns, which for a few thousand positions is most
    --- of what it costs; this reads each word once and clears the position it
    --- just reported out of a register.
    ---
    --- `target` is a pointer and a count because that is what a native kernel
    --- takes. Filling it here rather than allocating keeps a per-frame extraction
    --- allocation-free, and leaves the boundary where a native one would sit.
    ---
    --- @param target where positions are written, indexed from 0
    --- @param capacity how many positions `target` holds
    --- @param from the lowest position that may be written, counting from 0
    --- @return how many positions were written, and the position to resume from
    ---     when `target` filled first, or -1 when the set is exhausted
    --- @raises when capacity is negative
    function positionsInto(self, target: int32[?], capacity: integer, from: integer): (integer, integer)
        if capacity < 0 then
            error("bitset target capacity cannot be negative", 2)
        end

        local start = from < 0 ? 0 : from
        local first = rshift(start, WORD_SHIFT)
        local used = self.used
        if first >= used then
            return 0, -1
        end
        if capacity == 0 then
            return 0, start
        end

        local words = self.words
        local offset = band(start, BIT_MASK)
        local written = 0
        -- Both loops are bounded. The inner one cannot run past a word's width,
        -- and an unbounded loop here would be an inner loop LuaJIT re-detects on
        -- every pass of whatever loop the extraction sits in.
        unsafe do
            for word = first, used - 1 do
                local bits = tobit(words[word])
                if word == first and offset ~= 0 then
                    bits = band(bits, bnot(lshift(1, offset) - 1))
                end

                local base = lshift(word, WORD_SHIFT)
                for _ = 1, BITS_PER_WORD do
                    if bits == 0 then
                        break
                    end

                    local position = base + lowestBit(bits)
                    if written >= capacity then
                        return written as integer, position
                    end
                    target[written] = position
                    written = (written + 1) as integer
                    -- Clearing the lowest set bit is cheaper than masking the
                    -- word again from the position just reported.
                    bits = band(bits, bits - 1)
                end
            end
        end

        return written as integer, -1
    end

    --- Whether every bit set in `other` is also set here.
    --- @param other read and not modified
    --- @return true when `other` is a subset. An empty `other` is contained by
    ---     anything.
    function containsAll(self, other: Bitset): boolean
        local otherUsed = other.used
        if otherUsed == 0 then
            return true
        end
        if self.used < otherUsed then
            return false
        end

        local words, theirWords = self.words, other.words
        unsafe do
            for word = 0, otherUsed - 1 do
                local theirs = tobit(theirWords[word])
                if band(tobit(words[word]), theirs) ~= theirs then
                    return false
                end
            end
        end

        return true
    end

    --- Whether at least one bit is set in both. Early-exiting, and deliberately
    --- not an intersection followed by a count.
    --- @param other read and not modified, as is the receiver
    --- @return true when the two share a set bit
    function overlaps(self, other: Bitset): boolean
        local limit = self.used < other.used ? self.used : other.used

        local words, theirWords = self.words, other.words
        unsafe do
            for word = 0, limit - 1 do
                if band(tobit(words[word]), tobit(theirWords[word])) ~= 0 then
                    return true
                end
            end
        end

        return false
    end

    --- Whether the two share no set bit.
    --- @param other read and not modified, as is the receiver
    --- @return the negation of `overlaps`
    function disjoint(self, other: Bitset): boolean
        return not self:overlaps(other)
    end

    --- Replaces these bits with a copy of `other`'s. The two are independent
    --- afterwards, and this keeps its own capacity when that is the larger.
    --- @param other read and not modified
    function copyFrom(self, other: Bitset): nil
        local otherUsed = other.used
        if otherUsed > self.capacity then
            self:reserve(lshift(otherUsed, WORD_SHIFT))
        end

        if otherUsed > 0 then
            ffi.copy(self.words as any, other.words as any, otherUsed * 4)
        end
        local words = self.words
        unsafe do
            for word = otherUsed, self.used - 1 do
                words[word] = 0
            end
        end

        self.used = otherUsed
        self.population = other.population
        self.stale = other.stale
    end

    --- Adds every bit set in `other`.
    ---
    --- One bitwise operation per word: the population is marked for recount
    --- rather than tracked, and there is no per-word test for whether the word
    --- changed, because that branch costs more than the write it saves.
    --- @param other read and not modified
    function orWith(self, other: Bitset): nil
        local otherUsed = other.used
        if otherUsed == 0 then
            return
        end
        if otherUsed > self.capacity then
            self:reserve(lshift(otherUsed, WORD_SHIFT))
        end

        -- Hoisted after `reserve`, the only call above that can replace the array.
        local words, theirWords = self.words, other.words
        unsafe do
            for word = 0, otherUsed - 1 do
                words[word] = bor(tobit(words[word]), tobit(theirWords[word]))
            end
        end

        if otherUsed > self.used then
            self.used = otherUsed
        end
        self.stale = true
    end

    --- Keeps only the bits also set in `other`.
    --- @param other read and not modified. Words beyond the ones it uses are
    ---     cleared, so an empty `other` empties the receiver.
    function andWith(self, other: Bitset): nil
        local used = self.used
        if used == 0 then
            return
        end

        local shared = used < other.used ? used : other.used
        local words, theirWords = self.words, other.words
        unsafe do
            for word = 0, shared - 1 do
                words[word] = band(tobit(words[word]), tobit(theirWords[word]))
            end
            for word = shared, used - 1 do
                words[word] = 0
            end
        end

        -- Words at or above `shared` are now zero, so the bound narrows here for
        -- free. It is not otherwise scanned back.
        self.used = shared
        self.stale = true
    end

    --- Removes every bit set in `other`.
    --- @param other read and not modified. Words beyond the ones it uses keep
    ---     their bits, so an empty `other` changes nothing.
    function andNotWith(self, other: Bitset): nil
        local limit = self.used < other.used ? self.used : other.used
        if limit == 0 then
            return
        end

        local words, theirWords = self.words, other.words
        unsafe do
            for word = 0, limit - 1 do
                words[word] = band(tobit(words[word]), bnot(tobit(theirWords[word])))
            end
        end

        self.stale = true
    end

    --- Keeps only the bits set in exactly one of the two.
    --- @param other read and not modified
    function xorWith(self, other: Bitset): nil
        local otherUsed = other.used
        if otherUsed == 0 then
            return
        end
        if otherUsed > self.capacity then
            self:reserve(lshift(otherUsed, WORD_SHIFT))
        end

        local words, theirWords = self.words, other.words
        unsafe do
            for word = 0, otherUsed - 1 do
                words[word] = bxor(tobit(words[word]), tobit(theirWords[word]))
            end
        end

        if otherUsed > self.used then
            self.used = otherUsed
        end
        self.stale = true
    end
end

--- Creates an empty set.
--- @param capacityBits how many bits to allocate for. A starting size only:
---     setting a position past it grows rather than failing.
--- @return a set with nothing in it, whatever capacity was asked for
--- @export
function bitset.create(capacityBits: integer?): bitset.Bitset
    local words = wordsFor(capacityBits ?? DEFAULT_BITS)

    return new bitset.Bitset(
        words = ffi.new("uint32_t[?]", words) as uint32[?],
        capacity = words,
        used = 0,
        population = 0,
        stale = false
    )
end

export = bitset
]=],
["/nupp/data/crc32.nupp"] = [=[
module nupp.data.crc32

--[[
CRC-32 as zlib and PNG compute it: the reflected 0xedb88320 polynomial over a
256-entry table, with the running value complemented at both ends.

Passing a previous checksum continues one sum across several buffers, so a caller
streaming bytes never has to hold them all at once:

```nupp
local checksum = crc32(header)
checksum = crc32(body, checksum)
```

A checksum detects accidental damage. It does not authenticate anything, and it is
not hard to produce a collision for deliberately.
]]

local TABLE = {}
for entry = 0, 255 do
    local current = entry
    for _ = 1, 8 do
        current = bit.bxor(bit.rshift(current, 1), bit.band(current, 1) ~= 0 and 0xedb88320 or 0)
    end
    TABLE[entry] = current
end

--- Checksums bytes with CRC-32.
---
--- @param value the bytes to checksum
--- @param previous a checksum to continue from, or nil to start one
--- @return the checksum, as an unsigned 32-bit integer
--- @raises when previous is not an unsigned 32-bit integer
local function crc32(value: string | nupp.io.ByteView, previous: integer?): integer
    local carried = previous
    if carried == nil then
        carried = 0
    elseif carried < 0 or carried > 4294967295 then
        error("nupp: crc32 previous checksum must be an unsigned 32-bit integer", 2)
    end
    local current = bit.bnot(carried)
    local bytes = type(value) == "string" and value as string or (value as nupp.io.ByteView):getString()
    for index = 1, #bytes do
        current = bit.bxor(bit.rshift(current, 8), TABLE[bit.band(bit.bxor(current, bytes:byte(index)), 255)])
    end
    local answer = bit.bnot(current)

    return answer < 0 and answer + 4294967296 or answer
end

export = crc32
]=],
["/nupp/data/fnv1a64.nupp"] = [=[
module nupp.data.fnv1a64

--[[
FNV-1a over 64 bits, rendered as sixteen lowercase hex digits.

A fast non-cryptographic identity, for keying and bucketing. Use
[](nupp.data.sha256) where the digest has to stand up to someone choosing the
input.

LuaJIT numbers cannot hold a 64-bit product exactly, so the state is carried as two
32-bit halves and the prime is applied to each: 435 is the low half of 0x100000001b3
and the 256 shift is its high half reaching the high word. `bit.tobit` wraps each
half back into 32 bits the way the multiply would have.
]]

--- Hashes bytes with FNV-1a.
---
--- @param value the bytes to hash
--- @return the hash, as sixteen lowercase hex digits
local function fnv1a64(value: string | nupp.io.ByteView): string
    local bytes = type(value) == "string" and value as string or (value as nupp.io.ByteView):getString()
    local hi = 0xcbf29ce4
    local lo = 0x84222325
    for index = 1, #bytes do
        lo = bit.bxor(lo, bytes:byte(index))
        local low = lo < 0 and lo + 4294967296 or lo
        local high = hi < 0 and hi + 4294967296 or hi
        local product = low * 435
        local carry = math.floor(product / 4294967296)
        lo = bit.tobit(product)
        hi = bit.tobit(high * 435 + low * 256 + carry)
    end
    local high = hi < 0 and hi + 4294967296 or hi
    local low = lo < 0 and lo + 4294967296 or lo

    return string.format("%08x%08x", high, low)
end

export = fnv1a64
]=],
["/nupp/data/init.nupp"] = [=[
module nupp.data

--[[
Bytes in, values out.

Serialization, Unicode, identifiers, byte digests and bitsets. Every member is a
module of its own, reached by the name it has: `nupp.data.json`, `nupp.data.utf8`,
`nupp.data.sha256`. Nothing is re-exported here, so there is one name for each
facility and one place its documentation lives.

```nupp
const uuid7 = require("nupp.data.uuid7")
const sha256 = require("nupp.data.sha256")

local eventID = uuid7()
local digest = sha256("payload")
```

Which of these is native is not part of the contract. Some are generated Lua, some
stand on a shared Rust provider, and a program that never reaches one carries
neither its code nor its library. The build decides that from what the generated
code actually uses; a caller writes the same thing either way.
]]
]=],
["/nupp/data/json.nupp"] = [=[
module nupp.data.json

--[[
JSON encoding and decoding, and the values a Lua table cannot express by itself.

The work is simdjson's, reached through the `jsonNative` host boundary this module
loads. Nothing is reimplemented here: the module is the name a program uses and the
place the load is arranged, so a checked program never names the host.

`decodeAs`, `encodeAs` and `encodeRecord` are not the host's. They are installed onto
this table by the derive runtime when a program derives JSON for a type, because they
answer in terms of a derived entry rather than a document alone. They are declared
with the rest of the surface so a caller sees one API, and they raise when nothing
was derived.
]]

-- Normally the rock is on the path and this does nothing. A build that carries the
-- shared object without registering it names it in NUPP_JSON_LIBRARY instead, so the
-- boundary is opened directly rather than failing on a name Lua cannot find.
do
    local found = pcall(require, "jsonNative")
    if not found then
        local path = os.getenv("NUPP_JSON_LIBRARY")
        local open = path and package.loadlib(path, "luaopen_jsonNative") or nil
        if not open then
            error("nupp: JSON runtime is unavailable", 0)
        end
        package.loaded.jsonNative = (open as function(): any)()
    end
end

const native = require("jsonNative")

--- Values that can encode themselves as JSON text.
---
--- Declared here rather than aliased out of the host boundary, because this is the
--- name callers write: `derive.JSON` answers a contract in terms of it. `Writer` is
--- not declared here, because nothing names it as a type -- it is reached as a value
--- from `writer()`.
export interface JSONEncodable
    toJSON: function(self): string
end

export = native
]=],
["/nupp/data/jsonnative.d.nupp"] = [=[
@!internal

--[[
JSON encoding and decoding, and the values a Lua table cannot express by itself.

This is the surface of the simdjson-backed host module. Programs reach it as
`nupp.data.json`, which loads this boundary and re-exports it, so the shape is
declared here and nowhere else.

`decodeAs`, `encodeAs` and `encodeRecord` are not the host's. The derive runtime
installs them onto this table when a program derives JSON for a type, and they raise
when nothing was derived. They are declared with the rest so a caller sees one API.
]]

--- Values that can encode themselves as JSON text.
record json
    --- Values that can encode themselves as JSON text.
    interface JSONEncodable
        toJSON: function(self): string
    end

    --- A checked incremental JSON writer.
    interface Writer
        --- Starts an array value.
        --- @param self this writer
        --- @return this writer
        startArray: function(self: Writer): Writer

        --- Starts an object value.
        --- @param self this writer
        --- @return this writer
        startObject: function(self: Writer): Writer

        --- Selects the next object member.
        --- @param self this writer
        --- @param name the next object member name
        --- @return this writer
        key: function(self: Writer, name: string): Writer

        --- Appends one complete Lua value.
        --- @param self this writer
        --- @param value the next complete JSON value
        --- @return this writer
        write: function(self: Writer, value: any): Writer

        --- Appends JSON null.
        --- @param self this writer
        --- @return this writer
        null: function(self: Writer): Writer

        --- Closes the current array or object.
        --- @param self this writer
        --- @return this writer
        close: function(self: Writer): Writer

        --- Returns bytes completed since the previous flush.
        --- @param self this writer
        --- @return the completed JSON bytes
        flush: function(self: Writer): string

        --- Completes the document and returns its final bytes.
        --- @param self this writer
        --- @return the final JSON bytes
        finish: function(self: Writer): string
    end

    --- Decodes one JSON document. Null members are dropped unless a replacement
    --- value is supplied.
    --- @param text the complete JSON document
    --- @param nullValue the value used for JSON null, or nil to drop nulls
    --- @return the decoded Lua value
    decode: function(text: string, nullValue: any?): any

    --- Materializes only the fields selected by an On-Demand pull shape.
    --- @param text the complete JSON document
    --- @param shape the fields and array members to materialize
    --- @param nullValue the value used for JSON null, or nil to drop nulls
    --- @return the selected Lua value
    pull: function(text: string, shape: any, nullValue: any?): any

    --- Applies one pull shape to every member of an array.
    --- @param shape the selection applied to each member, or every value when
    ---     omitted
    --- @return an array pull shape
    arrayOf: function(shape: any?): table

    --- Marks a Lua table as a JSON array, including while it is empty.
    --- @param value the table to mark
    --- @return the same table
    asArray: function<T is table>(takes value: T): T preserves value

    --- Marks a Lua table as a JSON object.
    --- @param value the table to mark
    --- @return the same table
    asObject: function<T is table>(takes value: T): T preserves value

    --- Serializes one Lua value as JSON.
    --- @param value the value to serialize
    --- @param nullValue an additional value treated as JSON null
    --- @return the JSON document
    encode: function(value: any, nullValue: any?): string

    --- Alias of `encode`.
    --- @param value the value to serialize
    --- @param nullValue an additional value treated as JSON null
    --- @return the JSON document
    serialize: function(value: any, nullValue: any?): string

    --- Creates an incremental JSON writer.
    --- @param nullValue an additional value treated as JSON null
    --- @return a new writer
    writer: function(nullValue: any?): Writer

    --- Decodes JSON into the nominal record named by its one type witness.
    --- @param type the record's type witness, naming what to decode into
    --- @param text the JSON document to decode
    --- @return the decoded record, or nil when the document does not fit it
    --- @return why it did not fit, when unsuccessful
    decodeAs: function<T>(type: Type<T>, text: string): (T?, string?)

    --- Encodes a nominal record after explicitly supplying its type witness.
    --- @param type the record's type witness
    --- @param value the record to encode
    --- @return the encoded JSON document
    encodeAs: function<T>(type: Type<T>, value: T): string

    --- Encodes a nominal record using the metatable its value already carries.
    --- @param value the record to encode
    --- @return the encoded JSON document
    encodeRecord: function<T>(value: T): string

    --- Sentinel that decodes from and encodes as JSON null.
    NULL: any

    --- An explicit empty JSON array.
    EMPTY_ARRAY: table

    --- An explicit empty JSON object.
    EMPTY_OBJECT: table

end

--- @local
local value: json

return value
